insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:fundamentos-vocais')::uuid, 'fundamentos-vocais', 'A', 'Fundamentos vocais', 'Postura, respiração, emissão e cuidado com a voz', 'A base técnica de quem canta: um corpo disponível, ar bem administrado, som livre, texto claro e uma rotina segura de aquecimento. Cada aula traz prática guiada e critérios para avançar.', 'mic-vocal', 0) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:postura-e-relaxamento')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'postura-e-relaxamento', 'Postura e relaxamento', 'Um corpo alinhado e sem tensões desnecessárias deixa o ar e o som circularem.', 0, 1, 15, '{"objetivo":"Encontrar uma postura alinhada e relaxada, de pé e sentado, que favoreça a respiração e a emissão, e reconhecer as tensões mais comuns ao cantar.","explicacao":[{"type":"p","text":"A voz não acontece só na garganta: ela depende do corpo inteiro. Quando o corpo está alinhado, os músculos da respiração trabalham com liberdade e a laringe não precisa compensar. Quando há tensão (ombros erguidos, queixo para frente, joelhos travados), o som fica mais apertado e cansamos mais rápido."},{"type":"list","items":["Pés afastados na largura do quadril, peso distribuído entre calcanhares e dedos.","Joelhos destravados (nem dobrados, nem esticados ao extremo).","Quadril em posição neutra, sem empinar nem encaixar demais.","Coluna longa e peito aberto, sem estufar ou arquear as costas.","Ombros soltos, para baixo e levemente para trás.","Cabeça equilibrada sobre a coluna, queixo paralelo ao chão.","Mandíbula solta, língua relaxada encostando nos dentes de baixo."]},{"type":"tip","title":"Postura não é rigidez","text":"Pense em “alto e solto”: imagine um fio puxando suavemente o topo da cabeça para cima, enquanto ombros e braços pesam para baixo. Se você precisa fazer força para manter a postura, ela está rígida demais."},{"type":"p","text":"Sentado(a), use a parte da frente da cadeira, com os dois pés apoiados no chão e a coluna sem encostar no encosto. Assim o abdômen fica livre para a respiração — o que é importante nos ensaios longos."}],"demonstracao":[{"type":"p","text":"Use as notas abaixo para fazer o “hum” de boca fechada. Escolha a que soar mais próxima da sua fala: o objetivo é sentir vibração nos lábios e no rosto, sem esforço."},{"type":"audio","label":"Nota para “hum” — vozes femininas (Lá3)","notes":["A3"],"tempo":30},{"type":"audio","label":"Nota para “hum” — vozes masculinas (Lá2)","notes":["A2"],"tempo":30},{"type":"toolLink","tool":"gravador","label":"Grave-se cantando uma frase curta em postura “largada” e depois alinhada, e compare"}],"exercicioGuiado":{"intro":"Faça devagar, prestando atenção às sensações. Leva cerca de 5 minutos.","passos":["De pé, feche os olhos e perceba o peso do corpo nos pés. Balance levemente para frente e para trás até encontrar o centro.","Destrave os joelhos e imagine o fio no topo da cabeça alongando a coluna.","Eleve os ombros até as orelhas ao inspirar e deixe-os cair ao expirar. Repita 3 vezes; depois role os ombros para trás 5 vezes.","Com as pontas dos dedos, massageie a musculatura da bochecha perto da articulação da mandíbula, deixando a boca entreaberta.","Com a boca fechada e a mandíbula solta por dentro, faça um “hum” na nota de referência por 5 segundos. Sinta a vibração nos lábios.","Sente-se na frente da cadeira e repita o “hum”, mantendo o mesmo alinhamento."]},"pratiqueSozinho":{"passos":["Antes de cada estudo ou ensaio, faça o checklist de postura (1 minuto).","Cante uma frase de um hino conhecido observando-se no espelho: queixo, ombros e mandíbula ficaram soltos?","Repita a mesma frase sentado(a)."],"minutos":5,"frequencia":"Todos os dias, antes de cantar"},"errosComuns":[{"erro":"Erguer o queixo para alcançar notas agudas.","correcao":"Mantenha o queixo paralelo ao chão. A nota aguda não está “em cima”; erguer a cabeça tensiona a laringe."},{"erro":"Estufar o peito e travar a barriga.","correcao":"O peito fica aberto, mas o abdômen precisa estar livre para se mover com a respiração."},{"erro":"Travar os joelhos durante músicas longas.","correcao":"Joelhos destravados evitam tensão nas costas e até tontura em pé por muito tempo."},{"erro":"Ombros que sobem ao inspirar.","correcao":"A inspiração acontece embaixo (costelas e abdômen). Pratique inspirar com as mãos nos ombros para perceber."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo).","Se sentir tontura durante alongamentos ou respirações, sente-se e volte à respiração normal."],"criterioAvanco":"Acertar pelo menos 70% da avaliação desta aula e conseguir cantar uma frase mantendo ombros, pescoço e mandíbula soltos (confira gravando-se ou com o professor)."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'postura-relaxamento' from public.lessons where slug = 'postura-e-relaxamento' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:postura-checklist')::uuid, 'postura-checklist', (select id from public.lessons where slug = 'postura-e-relaxamento'), 'Checklist de postura', 'Fique em frente a um espelho e confira cada item, primeiro de pé e depois sentado(a).', 'self_check', '{"minutes":3,"items":["Pés na largura do quadril e peso distribuído","Joelhos destravados","Ombros soltos, sem subir ao inspirar","Queixo paralelo ao chão","Mandíbula solta no “hum”","Mesmo alinhamento quando sentado(a)"]}'::jsonb, 'postura-relaxamento', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:postura-avaliacao')::uuid, 'postura-avaliacao', (select id from public.lessons where slug = 'postura-e-relaxamento'), 'Avaliação: postura para cantar', 'Responda com base no que você estudou na aula.', 'quiz', '{"questions":[{"q":"Qual imagem ajuda a encontrar uma postura alinhada sem rigidez?","options":["Um fio puxando o topo da cabeça para cima, com ombros pesando para baixo","Peito estufado e barriga travada","Queixo erguido para o som ir “para cima”","Joelhos esticados ao máximo"],"answer":0,"explanation":"“Alto e solto”: a coluna se alonga enquanto ombros e braços ficam relaxados."},{"q":"Por que não se deve erguer o queixo para cantar notas agudas?","options":["Porque tensiona o pescoço e a laringe","Porque a nota fica mais grave","Porque o som fica mais alto","Não há problema em erguer o queixo"],"answer":0,"explanation":"Erguer a cabeça estica a musculatura do pescoço e dificulta a emissão livre."},{"q":"Ao cantar sentado(a), qual é a melhor posição?","options":["Na parte da frente da cadeira, pés no chão e coluna sem encostar","Recostado(a) no encosto, pernas cruzadas","Na ponta da cadeira com os pés para trás e o corpo inclinado para frente","Qualquer posição, a postura só importa em pé"],"answer":0},{"q":"O que acontece com os ombros numa inspiração eficiente?","options":["Permanecem soltos; a expansão acontece nas costelas e no abdômen","Sobem para encher mais o pulmão","Vão para frente","Ficam contraídos para dar apoio"],"answer":0},{"q":"Para que serve o “hum” de boca fechada nesta aula?","options":["Sentir a vibração do som sem esforço, com a mandíbula solta","Cantar o mais forte possível","Testar a nota mais aguda","Descansar a voz sem produzir som"],"answer":0}]}'::jsonb, 'postura-relaxamento', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:aquecimento-vocal')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'aquecimento-vocal', 'Aquecimento e desaquecimento vocal', 'Uma rotina curta e progressiva prepara a voz para cantar com segurança.', 1, 1, 20, '{"objetivo":"Conhecer e executar uma rotina de aquecimento de 8 a 10 minutos — corpo, respiração, vibração, deslizes e articulação — e um desaquecimento de 2 minutos após o ensaio.","explicacao":[{"type":"p","text":"As pregas vocais são um tecido delicado coordenado por pequenos músculos. Assim como um atleta não corre sem alongar, quem canta precisa preparar a musculatura aos poucos: do mais suave para o mais intenso, da região média para as extremidades, do som fechado para o aberto."},{"type":"list","ordered":true,"items":["Corpo (1 min): alongar pescoço lateralmente, rolar ombros, soltar a mandíbula.","Respiração (1 min): inspirar pelo nariz expandindo costelas; soltar o ar em “sss” contínuo por 8 a 12 tempos.","Vibração (2 min): vibração de lábios (“brrr”) ou de língua (“trrr”) em notas sustentadas e pequenas escalas.","Deslizes (2 min): sirene suave em “u” do grave ao agudo confortável e de volta, sem empurrar.","Escalas em vogais (2 min): cinco notas (Dó–Ré–Mi–Fá–Sol–Fá–Mi–Ré–Dó) em “mi”, “mê”, “má”, “mô”, “mu”, subindo meio-tom por vez até o limite confortável.","Articulação (1 min): trava-línguas e as consoantes do repertório do dia."]},{"type":"tip","title":"Por que a vibração de lábios funciona","text":"Ela cria uma leve resistência na saída do ar que equilibra a pressão sobre as pregas vocais. É um dos exercícios mais seguros para começar o dia e para recuperar a voz depois do ensaio."},{"type":"p","text":"O desaquecimento leva a voz de volta à fala: após o ensaio, faça 1 minuto de vibração de lábios em deslizes descendentes e alguns bocejos-suspiros suaves, terminando na sua altura de fala."}],"demonstracao":[{"type":"audio","label":"Escala de cinco notas em Dó (vozes femininas)","notes":["C4","D4","E4","F4","G4","F4","E4","D4","C4"],"tempo":120},{"type":"audio","label":"Escala de cinco notas em Dó (vozes masculinas)","notes":["C3","D3","E3","F3","G3","F3","E3","D3","C3"],"tempo":120},{"type":"audio","label":"Arpejo para deslize (Dó–Mi–Sol–Mi–Dó)","notes":["C4","E4","G4","E4","C4"],"tempo":100},{"type":"toolLink","tool":"aquecimento","label":"Abrir a rotina guiada de aquecimento com temporizador"}],"exercicioGuiado":{"intro":"Siga a rotina guiada na página “Treinar minha voz”. Ela toca as notas de referência e avança automaticamente.","passos":["Faça os alongamentos de pescoço e ombros (1 minuto).","Respire em 4 tempos e solte o ar em “sss” por 8 tempos. Repita 4 vezes.","Vibração de lábios na escala de cinco notas, começando numa nota média.","Sirene em “u”: suba e desça suavemente, como um elevador, sem forçar o topo.","Escala de cinco notas em “mi” e “má”, subindo meio-tom a cada repetição enquanto estiver confortável.","Termine com um trava-língua: “O rato roeu a roupa do rei de Roma”, articulado sem pressa."]},"pratiqueSozinho":{"passos":["Use a rotina guiada antes de cada estudo e antes do ensaio.","Depois de cantar, faça 1 minuto de vibração de lábios descendente e 3 suspiros suaves.","Registre o seu estudo em “Meu progresso” para manter a sequência de dias."],"minutos":10,"frequencia":"Todos os dias em que for cantar"},"errosComuns":[{"erro":"Começar pelas notas mais agudas e mais fortes.","correcao":"Comece na região média, com volume moderado, e expanda aos poucos."},{"erro":"Fazer a vibração de lábios com as bochechas tensas.","correcao":"Apoie levemente os dedos nas bochechas; o som deve sair contínuo, com pouco esforço."},{"erro":"Pular o desaquecimento depois do ensaio.","correcao":"Dois minutos de deslizes suaves ajudam a voz a se recuperar e voltar para a fala."},{"erro":"Achar que pigarrear limpa a voz.","correcao":"Pigarrear atrita as pregas vocais. Prefira engolir em seco ou tomar um gole de água."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo).","Aquecimento não deve doer nem cansar. Se cansar, diminua o volume e a extensão."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e completar a rotina guiada em 3 dias diferentes."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'aquecimento-vocal' from public.lessons where slug = 'aquecimento-vocal' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:aquecimento-rotina')::uuid, 'aquecimento-rotina', (select id from public.lessons where slug = 'aquecimento-vocal'), 'Rotina de aquecimento', 'Faça a rotina completa e avalie como cada etapa foi.', 'self_check', '{"minutes":10,"items":["Alongamentos sem dor","Respiração em “sss” por 8 tempos","Vibração de lábios contínua","Sirene sem empurrar o agudo","Escala de cinco notas em vogais","Desaquecimento após cantar"],"audio":{"notes":["C4","D4","E4","F4","G4","F4","E4","D4","C4"],"mode":"seq","tempo":120}}'::jsonb, 'aquecimento-vocal', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:aquecimento-avaliacao')::uuid, 'aquecimento-avaliacao', (select id from public.lessons where slug = 'aquecimento-vocal'), 'Avaliação: aquecimento seguro', 'Responda sobre os princípios do aquecimento vocal.', 'quiz', '{"questions":[{"q":"Qual é a ordem mais segura para aquecer a voz?","options":["Do suave para o intenso, da região média para as extremidades","Do agudo para o grave, sempre forte","Começar com o repertório mais difícil","Gritar um pouco para “abrir” a voz"],"answer":0},{"q":"Por que a vibração de lábios é um bom exercício inicial?","options":["Equilibra a pressão do ar sobre as pregas vocais com pouco esforço","Porque deixa a voz mais grave","Porque dispensa a respiração","Porque aumenta a extensão imediatamente"],"answer":0},{"q":"O que fazer em vez de pigarrear?","options":["Engolir em seco ou beber um gole de água","Pigarrear mais forte","Tossir","Sussurrar"],"answer":0,"explanation":"Sussurrar forçado e pigarrear também atritam as pregas vocais."},{"q":"Para que serve o desaquecimento?","options":["Levar a voz de volta para a fala e ajudar na recuperação","Treinar notas extremas","Substituir o aquecimento","Não tem utilidade"],"answer":0},{"q":"Na escala de cinco notas, até onde subir?","options":["Até onde estiver confortável, sem esforço","Sempre até a nota mais aguda possível","Exatamente uma oitava acima, para todos","Até a voz falhar"],"answer":0}]}'::jsonb, 'aquecimento-vocal', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:respiracao-e-fraseado')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'respiracao-e-fraseado', 'Respiração e fraseado', 'Administrar o ar com conforto e planejar onde respirar em cada frase.', 2, 1, 20, '{"objetivo":"Inspirar sem tensão, administrar a saída do ar para sustentar frases e planejar as respirações de uma música de acordo com o texto e a melodia.","explicacao":[{"type":"p","text":"Cantar exige mais ar e mais controle do que falar. Na inspiração, o diafragma desce e as costelas se expandem — por isso sentimos a cintura e as costas se abrirem. Na expiração cantada, o desafio é soltar o ar aos poucos, de forma constante, sem prender e sem empurrar."},{"type":"list","items":["Inspire pelo nariz quando houver tempo e pela boca nas respirações rápidas, sem barulho.","Sinta a expansão na cintura, nas costelas laterais e nas costas — não nos ombros.","Ao cantar, mantenha a sensação de “abertura” das costelas por mais tempo, em vez de esvaziar de uma vez.","Não encha o pulmão ao máximo: ar demais gera tensão. Inspire o necessário para a frase."]},{"type":"p","text":"Fraseado é a forma como conduzimos uma frase musical do início ao fim. Respirar no meio de uma palavra ou de uma ideia quebra o sentido do texto. Por isso marcamos na partitura (com uma vírgula ou um “V”) onde respirar, normalmente nas pausas, nas vírgulas do texto e no fim das frases."},{"type":"tip","title":"Respiração em grupo","text":"Num coral, frases muito longas podem ser cantadas com “respiração escalonada”: cada pessoa respira em um lugar diferente, discretamente, para que o som do naipe nunca pare. O diretor indica quando usar."}],"demonstracao":[{"type":"rhythm","pattern":"q q q q q q q q","bpm":60,"label":"Pulsação lenta (60 bpm) para contar a respiração"},{"type":"audio","label":"Frase para sustentar (vozes femininas)","notes":["G4","G4","A4","G4","F4","E4","D4","C4"],"tempo":66},{"type":"audio","label":"Frase para sustentar (vozes masculinas)","notes":["G3","G3","A3","G3","F3","E3","D3","C3"],"tempo":66},{"type":"toolLink","tool":"metronomo","label":"Abrir o metrônomo para contar os tempos"}],"exercicioGuiado":{"intro":"Use o metrônomo a 60 bpm (um tempo por segundo).","passos":["Mãos na cintura, polegares para trás: inspire em 4 tempos sentindo as mãos se afastarem.","Solte o ar em “sss” constante por 8 tempos. Depois tente 12 e 16, sem esvaziar de uma vez no início.","Repita com “fff” e depois com “vvv” (com som), mantendo a mesma constância.","Cante a frase de demonstração em “lu”, respirando somente no início. Se faltar ar, cante mais suave em vez de mais forte.","Escolha um hino conhecido, escreva a letra de uma estrofe e marque com “V” onde vai respirar."]},"pratiqueSozinho":{"passos":["3 séries de “sss” por 12 a 16 tempos.","Cante a estrofe que você marcou respeitando as respirações planejadas.","Grave-se e confira: alguma respiração cortou uma palavra ou uma ideia?"],"minutos":8,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Inspirar ruidosamente ou com os ombros.","correcao":"Abra a garganta como num bocejo discreto e deixe o ar entrar embaixo."},{"erro":"Gastar todo o ar nas primeiras notas.","correcao":"Comece a frase com o mesmo fluxo que pretende ter no final; pense em “economizar” as costelas abertas."},{"erro":"Prender o ar antes de cantar.","correcao":"A inspiração deve se transformar em som sem pausa travada na garganta."},{"erro":"Respirar no meio de uma palavra.","correcao":"Planeje as respirações no texto antes de cantar."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo).","Não prenda a respiração em exercícios longos. Se ficar tonto(a), pare e respire normalmente."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e sustentar um “sss” constante por 12 tempos a 60 bpm."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'respiracao-fraseado' from public.lessons where slug = 'respiracao-e-fraseado' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:respiracao-pratica')::uuid, 'respiracao-pratica', (select id from public.lessons where slug = 'respiracao-e-fraseado'), 'Prática de sustentação do ar', 'Use o metrônomo a 60 bpm e marque o que conseguiu.', 'self_check', '{"minutes":6,"items":["Inspiração sem subir os ombros","“sss” constante por 8 tempos","“sss” constante por 12 tempos","Frase cantada inteira com uma respiração","Respirações marcadas numa estrofe"]}'::jsonb, 'respiracao-fraseado', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:respiracao-avaliacao')::uuid, 'respiracao-avaliacao', (select id from public.lessons where slug = 'respiracao-e-fraseado'), 'Avaliação: respiração e fraseado', 'Responda sobre respiração e planejamento das frases.', 'quiz', '{"questions":[{"q":"Onde sentimos a expansão numa inspiração adequada para cantar?","options":["Cintura, costelas laterais e costas","Somente no peito alto","Nos ombros","Na garganta"],"answer":0},{"q":"Se o ar está acabando antes do fim da frase, o que é melhor fazer no estudo?","options":["Cantar mais suave e planejar uma respiração em lugar adequado","Empurrar o ar com força","Prender a respiração e continuar","Encher o pulmão ao máximo, até ficar tenso"],"answer":0},{"q":"Onde normalmente marcamos as respirações?","options":["Nas pausas, vírgulas do texto e finais de frase","No meio das palavras mais longas","Em qualquer lugar, quando faltar ar","Somente no início da música"],"answer":0},{"q":"O que é respiração escalonada?","options":["Cada cantor respira em um momento diferente para o som do naipe não parar","Respirar em degraus, cada vez mais fundo","Todos respiram juntos no mesmo ponto","Respirar apenas pelo nariz"],"answer":0},{"q":"Inspirar ar demais pode…","options":["Gerar tensão e dificultar o controle","Garantir mais afinação","Deixar a voz mais aguda","Não tem efeito"],"answer":0}]}'::jsonb, 'respiracao-fraseado', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:emissao-confortavel')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'emissao-confortavel', 'Emissão confortável e ressonância', 'Som livre e projetado sem apertar a garganta.', 3, 1, 20, '{"objetivo":"Produzir um som equilibrado — nem soproso, nem apertado — usando a ressonância para projetar a voz sem aumentar o esforço.","explicacao":[{"type":"p","text":"A emissão é o início do som. Ela pode ser soprosa (sai muito ar e pouca nota), apertada (a garganta fecha e o som fica duro) ou equilibrada (o som começa limpo, com o ar e as pregas vocais coordenados). O objetivo é a emissão equilibrada."},{"type":"p","text":"Ressonância é a amplificação do som nas cavidades acima das pregas vocais: garganta, boca e cavidade nasal. Ajustes pequenos — espaço na boca, posição da língua, a sensação de som “à frente” no rosto — fazem a voz ser ouvida com clareza sem gritar."},{"type":"list","items":["Ataque equilibrado: imagine dizer “ah” suavemente, como quem concorda com algo agradável.","Espaço interno: a sensação do início de um bocejo, com o palato mole elevado, sem abaixar a língua à força.","Som à frente: no “hum” e no “nhã”, sinta vibração nos lábios, nariz e maçãs do rosto.","Volume vem do equilíbrio entre ar e ressonância, não de apertar a garganta."]},{"type":"warning","text":"Rouquidão frequente, dor ou sensação de “bola” na garganta não são normais. Interrompa o exercício e procure um profissional de saúde (otorrinolaringologista ou fonoaudiólogo). Esta plataforma não faz diagnóstico."}],"demonstracao":[{"type":"audio","label":"Nota sustentada para “hum → á” (vozes femininas)","notes":["E4"],"tempo":20},{"type":"audio","label":"Nota sustentada para “hum → á” (vozes masculinas)","notes":["E3"],"tempo":20},{"type":"audio","label":"Padrão “nhã-nhã-nhã” (Sol–Fá–Mi–Ré–Dó)","notes":["G4","F4","E4","D4","C4"],"tempo":100},{"type":"toolLink","tool":"afinador","label":"Abrir o treinador de afinação para sustentar a nota"}],"exercicioGuiado":{"passos":["Diga “ã-hã” como quem concorda. Repita cantando numa nota confortável: esse é o ataque equilibrado.","Experimente um “ah” soproso (com muito ar) e um “ah” apertado. Depois volte ao equilibrado e perceba a diferença.","Faça “hum” na nota de referência e abra para “á” sem mudar a sensação de vibração à frente: “hummmm-á”.","Cante “nhã-nhã-nhã” descendo cinco notas. Depois cante a mesma melodia em “lá”, mantendo o brilho.","Cante uma frase de hino em volume médio e depois mais forte, apenas aumentando o ar e o espaço — sem apertar."]},"pratiqueSozinho":{"passos":["5 repetições de “hum → á” em notas confortáveis.","Padrão “nhã” → “lá” subindo meio-tom por vez.","Uma frase de hino em três volumes: suave, médio e forte."],"minutos":8,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Confundir volume com força na garganta.","correcao":"Aumente o volume com mais fluxo de ar e espaço interno; o pescoço continua solto."},{"erro":"Afundar a língua para “fazer espaço”.","correcao":"O espaço vem do palato mole elevado. A língua fica relaxada, tocando os dentes de baixo."},{"erro":"Som soproso por insegurança.","correcao":"Comece com o “ã-hã” de concordância para coordenar ar e voz."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e sustentar uma nota por 3 segundos com estabilidade no treinador de afinação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'emissao-ressonancia' from public.lessons where slug = 'emissao-confortavel' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:emissao-nota-sustentada')::uuid, 'emissao-nota-sustentada', (select id from public.lessons where slug = 'emissao-confortavel'), 'Nota sustentada com emissão equilibrada', 'Cante “lá” ou “ú” e sustente a nota. Com microfone, o sistema mede a estabilidade; sem microfone, faça a autoavaliação.', 'sing_note', '{"rounds":3,"holdSeconds":3,"toleranceCents":30}'::jsonb, 'afinacao-nota', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:emissao-avaliacao')::uuid, 'emissao-avaliacao', (select id from public.lessons where slug = 'emissao-confortavel'), 'Avaliação: emissão e ressonância', 'Responda sobre emissão e ressonância.', 'quiz', '{"questions":[{"q":"Qual é a emissão mais saudável e eficiente?","options":["Equilibrada","Soprosa","Apertada","Sussurrada"],"answer":0},{"q":"Ressonância é…","options":["A amplificação do som nas cavidades acima das pregas vocais","A força do ar no abdômen","O volume máximo da voz","Um tipo de respiração"],"answer":0},{"q":"Para cantar mais forte com segurança, devemos…","options":["Aumentar o fluxo de ar e o espaço interno, sem apertar a garganta","Apertar o pescoço","Erguer o queixo","Afundar a língua"],"answer":0},{"q":"Rouquidão frequente ao cantar indica que…","options":["É preciso parar e procurar um profissional de saúde","O exercício está funcionando","Deve-se cantar mais forte","A voz está aquecida"],"answer":0},{"q":"O “ã-hã” de concordância ajuda a…","options":["Coordenar o ar e as pregas vocais num ataque equilibrado","Treinar notas agudas","Respirar pelo nariz","Melhorar a dicção das consoantes"],"answer":0}]}'::jsonb, 'emissao-ressonancia', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:afinacao-basica')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'afinacao-basica', 'Afinação básica', 'Encontrar a nota de referência, reproduzi-la e sustentá-la.', 4, 1, 25, '{"objetivo":"Entender o que é afinação, reproduzir notas a partir de uma referência, sustentá-las e reconhecer tendências de cantar acima ou abaixo da nota.","explicacao":[{"type":"p","text":"Afinar é fazer a frequência da sua voz coincidir com a nota esperada. Cantar afinado e cantar com boa qualidade vocal são coisas diferentes: uma voz bonita pode estar desafinada, e uma voz simples pode estar perfeitamente afinada. No grupo, a afinação é o que faz os acordes soarem limpos."},{"type":"p","text":"A diferença entre duas alturas muito próximas é medida em cents: 100 cents são um semitom (de uma tecla para a vizinha no teclado). Diferenças de até cerca de 10 a 20 cents passam despercebidas para a maioria das pessoas; acima de 25 a 30 cents já soam “fora”."},{"type":"list","items":["Dificuldade auditiva: a pessoa não percebe se está acima ou abaixo. Treine primeiro a escuta (Laboratório: grave e agudo, perceber desafinação).","Dificuldade técnica: percebe, mas a voz não obedece (falta de ar, tensão, nota fora da região confortável).","Dificuldade de coordenação: acerta devagar, mas erra em frases rápidas ou com outras vozes soando."]},{"type":"tip","title":"Como encontrar a nota","text":"Ouça a referência em silêncio, imagine o som por dentro e só então cante, suave, numa vogal fechada (“u”). Se a nota estiver longe da sua região, cante-a uma oitava abaixo ou acima: a mesma nota em outra oitava também está afinada."},{"type":"p","text":"Quem tende a cantar abaixo (“calando”) costuma estar com pouco ar ou cansado; quem tende a cantar acima costuma estar com tensão ou ansiedade nas entradas. Uma única tentativa não diz que alguém é “desafinado”: observe a tendência ao longo de vários dias."}],"demonstracao":[{"type":"audio","label":"Nota de referência Dó4","notes":["C4"],"tempo":25},{"type":"audio","label":"Mesma nota em duas oitavas (Dó3 e Dó4)","notes":["C3","C4"],"tempo":50},{"type":"keyboard","from":"C3","to":"C5","highlight":["C3","C4","C5"],"label":"As notas Dó em três oitavas"},{"type":"toolLink","tool":"afinador","label":"Abrir o treinador de afinação com microfone"}],"exercicioGuiado":{"passos":["Toque a referência, ouça em silêncio por 2 segundos e cante “u” suave na mesma altura.","No treinador de afinação, sustente a nota e observe o ponteiro. Ajuste devagar até ficar no centro.","Cante de propósito um pouco acima e depois um pouco abaixo, e volte ao centro. Isso treina o controle.","Repita com três notas diferentes dentro da sua região confortável.","Faça o exercício de percepção: ouça se a segunda nota está afinada, acima ou abaixo."]},"pratiqueSozinho":{"passos":["Treinador de afinação: 5 notas sustentadas por dia.","Laboratório: “perceber desafinação” por 3 minutos.","Anote se a sua tendência é ficar acima ou abaixo."],"minutos":10,"frequencia":"5 vezes por semana"},"errosComuns":[{"erro":"Cantar antes de ouvir a nota por dentro.","correcao":"Ouça, imagine e só depois cante."},{"erro":"Começar a nota muito forte.","correcao":"Comece suave; é mais fácil ajustar a altura com volume moderado."},{"erro":"Desistir após uma tentativa errada.","correcao":"Afinação melhora com repetição curta e frequente. Compare a evolução por semanas, não por tentativas."},{"erro":"Forçar notas fora da região confortável.","correcao":"Cante a nota em outra oitava ou escolha outra nota de treino."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo).","A detecção pelo microfone é uma estimativa: ruído, eco e outros sons podem atrapalhar. Ela não é um diagnóstico."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações desta aula (percepção de desafinação e conceitos)."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
