insert into public.lesson_skills (lesson_id, skill_slug) select id, 'percepcao-afinacao' from public.lessons where slug = 'afinacao-basica' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:afinacao-sustentar-notas')::uuid, 'afinacao-sustentar-notas', (select id from public.lessons where slug = 'afinacao-basica'), 'Reproduzir e sustentar notas', 'Ouça a nota e cante-a sustentando. Use fones de ouvido se possível.', 'sing_note', '{"rounds":4,"holdSeconds":3,"toleranceCents":25}'::jsonb, 'afinacao-nota', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:afinacao-perceber-desafinacao')::uuid, 'afinacao-perceber-desafinacao', (select id from public.lessons where slug = 'afinacao-basica'), 'Avaliação: afinada, acima ou abaixo?', 'Ouça a referência e a segunda nota. Diga se a segunda está afinada, acima ou abaixo.', 'tuning_check', '{"rounds":8,"cents":45}'::jsonb, 'percepcao-afinacao', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:afinacao-avaliacao-conceitos')::uuid, 'afinacao-avaliacao-conceitos', (select id from public.lessons where slug = 'afinacao-basica'), 'Avaliação: conceitos de afinação', 'Responda sobre afinação.', 'quiz', '{"questions":[{"q":"Quantos cents há em um semitom?","options":["100","10","50","1200"],"answer":0},{"q":"Cantar a mesma nota uma oitava abaixo da referência é…","options":["Afinado: é a mesma nota em outra oitava","Desafinado","Uma terça","Um erro de ritmo"],"answer":0},{"q":"Uma pessoa percebe que está desafinada, mas a voz não obedece. Que tipo de dificuldade é mais provável?","options":["Técnica ou de coordenação","Auditiva","De leitura","Rítmica"],"answer":0},{"q":"O que fazer antes de cantar uma nota de referência?","options":["Ouvir e imaginar o som por dentro","Cantar o mais forte possível","Prender a respiração","Subir o queixo"],"answer":0},{"q":"Errar uma tentativa no treinador significa que a pessoa é desafinada?","options":["Não: é preciso observar a tendência ao longo de vários dias","Sim, sempre","Sim, se for a primeira tentativa","Depende do volume"],"answer":0}]}'::jsonb, 'afinacao-nota', 'avaliacao', 1, 2) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:diccao-e-articulacao')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'diccao-e-articulacao', 'Dicção e articulação', 'Texto compreensível, vogais unificadas e consoantes claras.', 5, 1, 15, '{"objetivo":"Cantar com texto inteligível, unificando as vogais com o grupo e articulando as consoantes no tempo certo, sem quebrar o legato.","explicacao":[{"type":"p","text":"Na música sacra, o texto é a mensagem. Se a congregação não entende as palavras, perdemos parte do propósito. Cantando, sustentamos as vogais — é nelas que está o som — e as consoantes aparecem rápidas e precisas, como “molduras” das vogais."},{"type":"list","items":["Vogais: sustente a vogal pura. Em “Deus”, cante “Dê-us”, mantendo o “ê” e colocando o “u” só no final.","Ditongos: a segunda vogal entra no último instante (“mãe” = “mã-e”, com o “e” bem no fim).","Consoantes finais: no grupo, todos devem soltar o “s” ou o “r” final juntos, exatamente no corte indicado pelo regente.","Consoantes iniciais: ataque-as um pouco antes do tempo para que a vogal caia no tempo.","Em português cantado, evite o “r” muito arrastado ou gutural; prefira o “r” vibrante simples ou suave, conforme a orientação do grupo."]},{"type":"tip","title":"Unidade de vogais","text":"Num naipe, cinco pessoas cantando “é” de cinco jeitos soam como cinco vozes separadas. Combinem a forma da boca: lábios levemente arredondados ajudam a unificar o som."}],"demonstracao":[{"type":"audio","label":"Nota para exercitar vogais (mi-mê-má-mô-mu)","notes":["D4","D4","D4","D4","D4"],"tempo":80},{"type":"rhythm","pattern":"e e e e e e e e","bpm":80,"label":"Ritmo para trava-línguas em colcheias"}],"exercicioGuiado":{"passos":["Fale e depois cante numa nota só: “mi – mê – má – mô – mu”, mudando apenas a vogal, sem mexer a mandíbula de forma exagerada.","Trava-línguas no ritmo de colcheias: “Três pratos de trigo para três tigres tristes”.","Cante a palavra “Senhor” em duas notas: sustente “Se-” e “-nhô” e solte o “r” somente no final.","Leia em voz alta a primeira estrofe de um hino, com calma, articulando bem. Depois cante mantendo a mesma clareza."]},"pratiqueSozinho":{"passos":["2 minutos de trava-línguas com metrônomo.","Cante uma estrofe sustentando as vogais e cortando as consoantes finais no tempo.","Grave e confira se o texto está compreensível."],"minutos":6,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Sustentar consoantes (“mmmmãe”, “Deusssss”).","correcao":"Sustente a vogal; a consoante é rápida."},{"erro":"Fechar a boca demais para articular.","correcao":"A articulação é feita com lábios e língua ágeis, não com a mandíbula travada."},{"erro":"Cada pessoa soltar o “s” final num momento diferente.","correcao":"Combine o corte com o regente e solte junto, sem exagero."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e gravar uma estrofe com o texto compreensível."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'diccao-articulacao' from public.lessons where slug = 'diccao-e-articulacao' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:diccao-pratica')::uuid, 'diccao-pratica', (select id from public.lessons where slug = 'diccao-e-articulacao'), 'Prática de dicção', 'Faça os exercícios e marque o que conseguiu com clareza.', 'self_check', '{"minutes":6,"items":["Vogais puras numa nota só","Trava-língua no ritmo sem tropeçar","Consoante final no tempo certo","Estrofe gravada com texto claro"]}'::jsonb, 'diccao-articulacao', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:diccao-avaliacao')::uuid, 'diccao-avaliacao', (select id from public.lessons where slug = 'diccao-e-articulacao'), 'Avaliação: dicção cantada', 'Responda sobre dicção e articulação.', 'quiz', '{"questions":[{"q":"Ao cantar, o som é sustentado principalmente nas…","options":["Vogais","Consoantes","Pausas","Respirações"],"answer":0},{"q":"Como cantar o ditongo de “mãe” numa nota longa?","options":["Sustentar “mã” e colocar o “e” no final","Sustentar o “e”","Alternar “ã” e “e”","Cantar só o “m”"],"answer":0},{"q":"Para que a vogal caia exatamente no tempo, a consoante inicial deve ser articulada…","options":["Um pouco antes do tempo","Depois do tempo","Junto com a respiração seguinte","Sem preocupação"],"answer":0},{"q":"Por que unificar as vogais no naipe?","options":["Para o naipe soar como uma só voz","Para cantar mais rápido","Para cantar mais agudo","Não é necessário"],"answer":0}]}'::jsonb, 'diccao-articulacao', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:extensao-tessitura-registros')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'extensao-tessitura-registros', 'Extensão, tessitura e registros', 'Conhecer a própria região confortável e transitar entre registros sem forçar.', 6, 2, 25, '{"objetivo":"Diferenciar extensão e tessitura, conhecer os registros vocais e identificar a própria região confortável sem forçar notas extremas.","explicacao":[{"type":"p","text":"Extensão vocal é o conjunto de todas as notas que uma pessoa consegue produzir, da mais grave à mais aguda — inclusive as que soam com esforço. Tessitura é a região em que a voz canta com conforto, boa qualidade e por bastante tempo. Para escolher a voz num arranjo, a tessitura é muito mais importante que a extensão."},{"type":"list","items":["Voz de peito: sensação de vibração no peito, som mais denso, usada nas regiões grave e média.","Voz de cabeça: sensação de vibração no rosto e na cabeça, som mais leve, usada na região aguda.","Coordenação intermediária (voz mista): equilíbrio entre os dois, permitindo transições suaves.","Região de passagem: notas em que a voz muda de registro. Pode “quebrar” no início; com treino, a transição fica suave. A identificação precisa da passagem deve ser feita com um professor."]},{"type":"tip","title":"Sem competição","text":"Ninguém canta melhor por alcançar a nota mais aguda ou mais grave. O que importa no ministério é cantar a sua parte com conforto e qualidade. Exercícios extremos podem machucar a voz."},{"type":"p","text":"A classificação tradicional (soprano, mezzo-soprano, contralto, tenor, barítono, baixo) considera tessitura, timbre e passagens. Por isso, aqui ela sempre começa como provisória e pode mudar: vozes se desenvolvem com o estudo."}],"demonstracao":[{"type":"keyboard","from":"E2","to":"C6","highlight":["C4"],"label":"Teclado de referência (Dó4 = dó central)"},{"type":"audio","label":"Deslize por arpejo (vozes femininas)","notes":["C4","E4","G4","C5","G4","E4","C4"],"tempo":100},{"type":"audio","label":"Deslize por arpejo (vozes masculinas)","notes":["C3","E3","G3","C4","G3","E3","C3"],"tempo":100},{"type":"toolLink","tool":"extensao","label":"Abrir o mapeamento da região confortável"}],"exercicioGuiado":{"passos":["Faça a sirene em “u” do grave ao agudo, bem suave, e observe onde a sensação de vibração muda do peito para a cabeça.","No mapeamento da região confortável, cante cada nota proposta e marque: confortável, com esforço ou não alcanço.","Pare de subir ou descer assim que sentir esforço. As notas “com esforço” fazem parte da extensão, não da tessitura.","Cante o arpejo Dó–Mi–Sol–Dó em “u”, passando pela região de passagem com volume suave."]},"pratiqueSozinho":{"passos":["Sirene suave em “u” por 1 minuto.","Arpejos leves atravessando a passagem em volume suave.","Refaça o mapeamento da região a cada 4 semanas para ver a evolução."],"minutos":6,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Empurrar a voz de peito cada vez mais alto.","correcao":"Deixe a voz ficar mais leve ao subir; a voz de cabeça e a voz mista existem para isso."},{"erro":"Achar que a voz “falhar” na passagem é defeito.","correcao":"É uma transição natural que se coordena com treino suave."},{"erro":"Escolher a parte do arranjo pela nota mais aguda que alcança.","correcao":"Escolha pela região onde canta com conforto durante a música inteira."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo).","Não procure as notas extremas: pare no primeiro sinal de esforço."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e concluir um mapeamento da região confortável."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'registros-extensao' from public.lessons where slug = 'extensao-tessitura-registros' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:registros-avaliacao')::uuid, 'registros-avaliacao', (select id from public.lessons where slug = 'extensao-tessitura-registros'), 'Avaliação: extensão, tessitura e registros', 'Responda sobre extensão, tessitura e registros.', 'quiz', '{"questions":[{"q":"Qual a diferença entre extensão e tessitura?","options":["Extensão é tudo o que se alcança; tessitura é a região confortável","São a mesma coisa","Tessitura é a nota mais aguda","Extensão é só a região grave"],"answer":0},{"q":"Para escolher a sua parte num arranjo, o mais importante é…","options":["A tessitura (região confortável)","A nota mais aguda que você alcança","A nota mais grave que você alcança","Cantar a melodia sempre"],"answer":0},{"q":"A voz “quebrar” ao passar do grave para o agudo indica…","options":["Uma região de passagem entre registros, que pode ser coordenada com treino","Que a pessoa não pode cantar","Uma doença","Que deve cantar mais forte"],"answer":0},{"q":"A classificação vocal nesta plataforma começa como…","options":["Provisória, podendo ser revista pelo professor","Definitiva","Obrigatória para cantar","Baseada só na nota mais aguda"],"answer":0},{"q":"Ao sentir esforço numa nota aguda, você deve…","options":["Parar de subir e voltar à região confortável","Insistir até conseguir","Cantar mais forte","Erguer o queixo"],"answer":0}]}'::jsonb, 'registros-extensao', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:interpretacao-musical')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'interpretacao-musical', 'Interpretação musical', 'Dinâmica, fraseado, legato e intenção do texto sacro.', 7, 2, 20, '{"objetivo":"Usar dinâmica, fraseado, legato e articulação para comunicar o sentido do texto, equilibrando emoção, técnica e inteligibilidade, em unidade com o grupo.","explicacao":[{"type":"p","text":"Interpretar é dar sentido às notas. A mesma melodia pode soar como uma oração íntima ou como um hino de vitória, dependendo de como a cantamos. O ponto de partida é sempre o texto: o que ele diz, para quem, com que sentimento."},{"type":"list","items":["Dinâmica: variações de intensidade. pp (pianíssimo), p (piano, suave), mp, mf, f (forte), ff. Crescendo (aumentar aos poucos) e decrescendo (diminuir).","Fraseado: cada frase tem uma direção, normalmente para uma palavra ou sílaba importante. Evite acentuar sílabas fracas.","Legato: notas ligadas, sem buracos entre elas. É o padrão do canto coral sacro.","Staccato e acentos: articulações curtas ou marcadas, usadas para efeito de texto.","Intenção: o rosto e a expressão também comunicam. Cante o texto, não apenas as notas."]},{"type":"tip","title":"Unidade sonora","text":"No grupo, a interpretação é combinada: todos crescem juntos, respiram juntos e cortam juntos. Emoção individual sem unidade vira desequilíbrio; técnica sem emoção vira execução fria. O regente conduz esse equilíbrio."}],"demonstracao":[{"type":"audio","label":"Frase em legato (Sol–Lá–Si–Dó–Si–Lá–Sol)","notes":["G4","A4","B4","C5","B4","A4","G4"],"tempo":72},{"type":"harmonyLink","arrangement":"hino-alegria-unissono","label":"Pratique dinâmica no “Hino da Alegria” em uníssono"}],"exercicioGuiado":{"passos":["Leia o texto de uma estrofe em voz alta e sublinhe a palavra mais importante de cada frase.","Cante a frase de demonstração em “lu” com legato, sem buracos entre as notas.","Cante a mesma frase com crescendo até a nota mais aguda e decrescendo até o fim.","Cante a estrofe escolhida dirigindo cada frase para a palavra sublinhada.","Grave e ouça: a interpretação combina com o texto?"]},"pratiqueSozinho":{"passos":["Escolha uma música do repertório e marque dinâmicas e respirações na letra.","Cante em três versões: sem dinâmica, com a dinâmica marcada e com exagero. Compare.","Leve as marcações para discutir no ensaio."],"minutos":10,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Acentuar a última sílaba das palavras (“Se-NHOR” em notas longas sem intenção).","correcao":"Respeite a acentuação natural da fala."},{"erro":"Cantar tudo no mesmo volume.","correcao":"Planeje pelo menos um crescendo e um momento suave em cada estrofe."},{"erro":"Confundir emoção com volume excessivo.","correcao":"Momentos suaves também emocionam; o grupo precisa de equilíbrio."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e apresentar ao professor uma estrofe com dinâmicas e respirações marcadas."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'interpretacao' from public.lessons where slug = 'interpretacao-musical' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:interpretacao-avaliacao')::uuid, 'interpretacao-avaliacao', (select id from public.lessons where slug = 'interpretacao-musical'), 'Avaliação: elementos de interpretação', 'Responda sobre interpretação musical.', 'quiz', '{"questions":[{"q":"O que significa “p” numa partitura?","options":["Piano: suave","Pausa","Pulsação","Passagem"],"answer":0},{"q":"Crescendo significa…","options":["Aumentar a intensidade aos poucos","Cantar mais agudo","Acelerar","Diminuir a intensidade"],"answer":0},{"q":"Legato é…","options":["Cantar as notas ligadas, sem interrupções","Cantar notas curtas","Cantar sem texto","Cantar mais forte"],"answer":0},{"q":"Qual deve ser o ponto de partida da interpretação de um hino?","options":["O sentido do texto","O volume máximo da voz","A nota mais aguda","O andamento mais rápido possível"],"answer":0},{"q":"Num grupo, a interpretação deve ser…","options":["Combinada, com unidade de dinâmicas, respirações e cortes","Individual, cada um do seu jeito","Sempre forte","Definida por quem canta mais alto"],"answer":0}]}'::jsonb, 'interpretacao', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:percepcao-musical')::uuid, 'percepcao-musical', 'B', 'Percepção musical', 'Aprender a ouvir antes de cantar', 'Treino auditivo progressivo: altura, reprodução de notas, intervalos, memória melódica, ritmo e acordes. Cada aula combina exemplos sonoros, prática no teclado e avaliação com feedback imediato.', 'ear', 1) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:grave-e-agudo')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'grave-e-agudo', 'Reconhecimento de notas graves e agudas', 'Perceber a direção do som: mais agudo, mais grave ou igual.', 0, 1, 15, '{"objetivo":"Perceber se uma nota é mais aguda, mais grave ou igual a outra, mesmo quando a diferença é pequena.","explicacao":[{"type":"p","text":"Altura é a característica que faz um som ser agudo (“fino”) ou grave (“grosso”). Ela depende da frequência: quanto mais vibrações por segundo, mais agudo o som. No teclado, as notas ficam mais agudas para a direita e mais graves para a esquerda."},{"type":"p","text":"Não confunda altura com volume: um som pode ser grave e forte, ou agudo e suave. Também não confunda com timbre: um violão e uma voz podem tocar exatamente a mesma altura."},{"type":"tip","title":"Use o corpo","text":"Ao ouvir duas notas, mova a mão para cima ou para baixo acompanhando a segunda nota. Muitas pessoas percebem melhor a direção com um gesto."}],"demonstracao":[{"type":"audio","label":"Grande diferença: Dó4 → Dó5","notes":["C4","C5"],"tempo":60},{"type":"audio","label":"Diferença média: Dó4 → Sol4","notes":["C4","G4"],"tempo":60},{"type":"audio","label":"Diferença pequena: Dó4 → Ré4","notes":["C4","D4"],"tempo":60},{"type":"audio","label":"Descendo: Sol4 → Mi4","notes":["G4","E4"],"tempo":60},{"type":"keyboard","from":"C3","to":"C5","label":"Toque teclas à esquerda (graves) e à direita (agudas)"}],"exercicioGuiado":{"passos":["Ouça cada demonstração e mova a mão para cima ou para baixo junto com a segunda nota.","No teclado, toque uma nota e depois outra à direita: confirme que a segunda é mais aguda.","Cante as duas notas da demonstração “Dó4 → Sol4” em “lá”, sentindo a voz subir.","Faça o exercício de prática e depois a avaliação."]},"pratiqueSozinho":{"passos":["Laboratório: “Grave ou agudo”, 5 minutos.","Ao ouvir hinos, perceba se cada frase sobe ou desce."],"minutos":5,"frequencia":"Diariamente na primeira semana"},"errosComuns":[{"erro":"Confundir “mais forte” com “mais agudo”.","correcao":"Preste atenção apenas na altura. O exercício toca as notas com o mesmo volume."},{"erro":"Responder antes de ouvir a segunda nota inteira.","correcao":"Espere a nota terminar; repita o áudio quantas vezes precisar."}],"seguranca":["Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% na avaliação com diferenças de 2 a 5 semitons."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'discriminacao-altura' from public.lessons where slug = 'grave-e-agudo' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:altura-pratica')::uuid, 'altura-pratica', (select id from public.lessons where slug = 'grave-e-agudo'), 'Prática: grande e média diferença', 'A segunda nota é mais aguda ou mais grave?', 'pitch_compare', '{"rounds":8,"minSemitones":5,"maxSemitones":12}'::jsonb, 'discriminacao-altura', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:altura-avaliacao')::uuid, 'altura-avaliacao', (select id from public.lessons where slug = 'grave-e-agudo'), 'Avaliação: grave ou agudo', 'As diferenças agora são menores.', 'pitch_compare', '{"rounds":10,"minSemitones":2,"maxSemitones":5}'::jsonb, 'discriminacao-altura', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:reproducao-de-notas')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'reproducao-de-notas', 'Reprodução de notas', 'Encontrar no teclado e na voz a nota que você ouviu.', 1, 1, 20, '{"objetivo":"Reproduzir notas isoladas com a voz e encontrá-las no teclado a partir de uma referência.","explicacao":[{"type":"p","text":"Reproduzir uma nota é ligar o que o ouvido percebe ao que a voz faz. Comece pela escuta interna: ouça a nota, “cante por dentro” e só depois cante em voz alta. No teclado, use uma nota de referência (o Dó) para se orientar: a nota misteriosa está acima ou abaixo? Perto ou longe?"},{"type":"list","items":["As teclas brancas seguem Dó, Ré, Mi, Fá, Sol, Lá, Si; depois o Dó se repete uma oitava acima.","As teclas pretas são os sustenidos (♯) e bemóis (♭). Dó♯ e Ré♭ são a mesma tecla.","O dó central do piano é o Dó4. Vozes masculinas costumam cantar uma oitava abaixo das femininas."]}],"demonstracao":[{"type":"keyboard","from":"C4","to":"C5","highlight":["C4","D4","E4","F4","G4","A4","B4","C5"],"label":"Notas naturais de Dó4 a Dó5"},{"type":"audio","label":"Referência Dó4 e depois Mi4","notes":["C4","E4"],"tempo":50},{"type":"audio","label":"Referência Dó4 e depois Lá4","notes":["C4","A4"],"tempo":50},{"type":"toolLink","tool":"teclado","label":"Abrir o teclado interativo com nomes das notas"}],"exercicioGuiado":{"passos":["Toque o Dó4 no teclado e cante-o em “lá” (homens: uma oitava abaixo).","Toque Mi4 e cante. Depois toque Sol4 e cante.","Peça a alguém (ou use o exercício) para tocar uma nota: cante-a primeiro e depois procure no teclado.","Use o treinador de afinação para conferir se a sua nota sustentada está no centro."]},"pratiqueSozinho":{"passos":["Exercício “Encontre a nota” (5 minutos).","Treinador de afinação: 3 notas sustentadas."],"minutos":8,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Procurar a nota aleatoriamente no teclado.","correcao":"Compare com a referência: acima ou abaixo? Perto ou longe? Depois teste as vizinhas."},{"erro":"Cantar a nota antes de ouvi-la por dentro.","correcao":"Faça um segundo de silêncio entre ouvir e cantar."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% em “Encontre a nota” com notas naturais."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'afinacao-nota' from public.lessons where slug = 'reproducao-de-notas' on conflict do nothing;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'discriminacao-altura' from public.lessons where slug = 'reproducao-de-notas' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:reproducao-cantar')::uuid, 'reproducao-cantar', (select id from public.lessons where slug = 'reproducao-de-notas'), 'Cantar a nota ouvida', 'Ouça e cante sustentando. Com microfone, o sistema estima a afinação.', 'sing_note', '{"rounds":3,"holdSeconds":3}'::jsonb, 'afinacao-nota', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:reproducao-teclado-avaliacao')::uuid, 'reproducao-teclado-avaliacao', (select id from public.lessons where slug = 'reproducao-de-notas'), 'Avaliação: encontre a nota no teclado', 'Ouça o Dó de referência e a nota misteriosa; encontre-a no teclado.', 'note_match', '{"rounds":8,"range":[60,72],"naturalOnly":true}'::jsonb, 'discriminacao-altura', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:intervalos-simples')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'intervalos-simples', 'Intervalos simples', 'Terças, quintas e oitavas: as distâncias que formam as harmonias.', 2, 1, 25, '{"objetivo":"Reconhecer pelo som e pelo nome os intervalos de terça maior, terça menor, quinta justa e oitava, ascendentes e simultâneos.","explicacao":[{"type":"p","text":"Intervalo é a distância entre duas notas. Medimos em semitons (cada tecla vizinha no teclado) e damos nomes pelo número de notas da escala que ele abrange: de Dó a Mi há três notas (Dó, Ré, Mi), então é uma terça."},{"type":"list","items":["Terça maior (4 semitons): Dó → Mi. Som luminoso.","Terça menor (3 semitons): Dó → Mi♭ ou Lá → Dó. Som mais introspectivo.","Quinta justa (7 semitons): Dó → Sol. Som aberto, estável.","Oitava (12 semitons): Dó → Dó. A mesma nota mais aguda."]},{"type":"p","text":"Melódico é quando as notas soam uma depois da outra; harmônico é quando soam juntas. Cantar em harmonia é, na prática, cantar intervalos harmônicos com outras pessoas: por isso esta aula é a base da divisão de vozes."},{"type":"tip","title":"Memorize com músicas","text":"A quinta justa aparece em “Brilha, brilha, estrelinha”; a quarta justa no início de “Graça Excelsa”. Associar intervalos a melodias conhecidas acelera o reconhecimento."}],"demonstracao":[{"type":"intervals","root":"C4","semitones":[3,4,7,12]},{"type":"staff","clef":"sol","notes":["C4","E4","G4","C5"],"label":"Dó, Mi, Sol e Dó na pauta"}],"exercicioGuiado":{"passos":["Toque cada intervalo da demonstração de forma melódica e depois harmônica.","Cante a nota grave e depois a aguda de cada intervalo (homens, uma oitava abaixo).","Compare terça maior e terça menor: qual soa mais luminosa?","Faça a prática com terça maior, quinta e oitava; depois a avaliação incluindo a terça menor."]},"pratiqueSozinho":{"passos":["Laboratório de intervalos no nível recomendado (5 minutos).","Cante as terças da escala de Dó: Dó–Mi, Ré–Fá, Mi–Sol…"],"minutos":8,"frequencia":"5 vezes por semana"},"errosComuns":[{"erro":"Confundir terça maior e menor.","correcao":"Pense em acorde maior (alegre) e menor (introspectivo). Ouça os dois lado a lado."},{"erro":"Confundir quinta e oitava.","correcao":"A oitava soa como a mesma nota repetida mais aguda; a quinta, como notas diferentes que combinam."}],"seguranca":["Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% na avaliação com terças, quinta e oitava."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'intervalos' from public.lessons where slug = 'intervalos-simples' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:intervalos-pratica')::uuid, 'intervalos-pratica', (select id from public.lessons where slug = 'intervalos-simples'), 'Prática: terça maior, quinta e oitava', 'Identifique o intervalo ascendente.', 'interval_id', '{"rounds":8,"intervals":[4,7,12],"direction":"asc"}'::jsonb, 'intervalos', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:intervalos-avaliacao')::uuid, 'intervalos-avaliacao', (select id from public.lessons where slug = 'intervalos-simples'), 'Avaliação: intervalos simples', 'Inclui a terça menor e intervalos harmônicos.', 'interval_id', '{"rounds":10,"intervals":[3,4,7,12],"direction":"mixed"}'::jsonb, 'intervalos', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:memoria-de-sequencias')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'memoria-de-sequencias', 'Memorização de sequências', 'Guardar e reproduzir pequenas melodias.', 3, 1, 20, '{"objetivo":"Memorizar sequências de 3 a 5 notas e reproduzi-las no teclado e com a voz.","explicacao":[{"type":"p","text":"Aprender a própria voz num arranjo depende de memória melódica: guardar a linha depois de ouvi-la algumas vezes. A estratégia é perceber o desenho da melodia (sobe, desce, repete), os saltos e a nota de chegada, em vez de tentar decorar nota por nota."},{"type":"list","items":["Ouça uma vez apenas observando o desenho (sobe/desce).","Ouça de novo cantando por dentro.","Cante em voz alta em “lá” ou com os nomes das notas.","Só então procure no teclado, partindo da primeira nota (que é informada)."]}],"demonstracao":[{"type":"audio","label":"Sequência que sobe por graus: Dó–Ré–Mi","notes":["C4","D4","E4"],"tempo":84},{"type":"audio","label":"Sequência com repetição: Sol–Sol–Mi–Dó","notes":["G4","G4","E4","C4"],"tempo":84},{"type":"audio","label":"Sequência com salto: Dó–Sol–Mi–Ré","notes":["C4","G4","E4","D4"],"tempo":84}],"exercicioGuiado":{"passos":["Ouça a primeira demonstração e desenhe no ar: sobe, sobe.","Cante-a em “lá” e depois com os nomes: Dó–Ré–Mi.","Toque no teclado a partir do Dó destacado.","Repita com as demais demonstrações e faça a prática."]},"pratiqueSozinho":{"passos":["Laboratório: memória melódica (5 minutos).","Escolha um trecho curto de um hino e aprenda de ouvido, sem partitura."],"minutos":8,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Tentar memorizar nota por nota.","correcao":"Memorize o desenho e os pontos de chegada."},{"erro":"Tocar rápido demais no teclado.","correcao":"Cante primeiro; o teclado confirma o que você já sabe."}],"seguranca":["Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% das notas em sequências de 4 notas."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'memoria-melodica' from public.lessons where slug = 'memoria-de-sequencias' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:memoria-pratica')::uuid, 'memoria-pratica', (select id from public.lessons where slug = 'memoria-de-sequencias'), 'Prática: sequências de 3 notas', 'Ouça e reproduza no teclado.', 'melody_memory', '{"rounds":5,"minLength":3,"maxLength":3,"maxLeap":2}'::jsonb, 'memoria-melodica', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:memoria-avaliacao')::uuid, 'memoria-avaliacao', (select id from public.lessons where slug = 'memoria-de-sequencias'), 'Avaliação: sequências de 4 notas', 'Ouça e reproduza no teclado.', 'melody_memory', '{"rounds":5,"minLength":4,"maxLength":4,"maxLeap":3}'::jsonb, 'memoria-melodica', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:ritmo-e-pulsacao')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'ritmo-e-pulsacao', 'Ritmo e pulsação', 'Sentir o pulso e reproduzir padrões rítmicos.', 4, 1, 20, '{"objetivo":"Sentir a pulsação, manter o andamento e reproduzir padrões rítmicos simples com semínimas, mínimas e colcheias.","explicacao":[{"type":"p","text":"Pulsação é a batida regular que sentimos na música — a que marcamos com o pé. O andamento é a velocidade dessa pulsação, medida em batidas por minuto (bpm). O ritmo é a combinação de durações curtas e longas sobre a pulsação."},{"type":"list","items":["Semínima: dura 1 tempo.","Mínima: dura 2 tempos.","Colcheia: dura meio tempo (duas colcheias por tempo).","Compasso 4/4: quatro tempos por compasso, com o primeiro mais forte."]},{"type":"tip","title":"Cantar junto começa no ritmo","text":"Num grupo, entrar meio tempo atrasado é tão perceptível quanto desafinar. Sentir a pulsação no corpo (pé, mão) dá segurança para as entradas."}],"demonstracao":[{"type":"rhythm","pattern":"q q q q","bpm":80,"label":"Quatro semínimas"},{"type":"rhythm","pattern":"h h","bpm":80,"label":"Duas mínimas"},{"type":"rhythm","pattern":"q e e q q","bpm":80,"label":"Semínima, duas colcheias, duas semínimas"},{"type":"toolLink","tool":"metronomo","label":"Abrir o metrônomo"}],"exercicioGuiado":{"passos":["Ligue o metrônomo a 80 bpm e bata o pé em cada clique.","Fale “tá” em cada tempo (semínimas). Depois “tá-a” para mínimas (dois tempos).","Fale “ti-ti” para duas colcheias dentro de um tempo.","Ouça cada demonstração e bata palmas junto. Depois faça o exercício tocando no botão."]},"pratiqueSozinho":{"passos":["Metrônomo: bata o pé por 1 minuto em 60, 80 e 100 bpm.","Laboratório de ritmo (5 minutos)."],"minutos":7,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Acelerar nas notas curtas.","correcao":"As colcheias cabem dentro do tempo: o pulso não muda."},{"erro":"Encurtar notas longas.","correcao":"Conte mentalmente os tempos das mínimas até o fim."}],"seguranca":["Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% na avaliação de padrões rítmicos."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'ritmo-pulsacao' from public.lessons where slug = 'ritmo-e-pulsacao' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:ritmo-pratica')::uuid, 'ritmo-pratica', (select id from public.lessons where slug = 'ritmo-e-pulsacao'), 'Prática: semínimas e mínimas', 'Ouça a contagem e o ritmo; depois toque o mesmo ritmo.', 'rhythm_tap', '{"rounds":4,"patterns":["q q q q","h h","q q h","h q q"],"bpm":80}'::jsonb, 'ritmo-pulsacao', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:ritmo-avaliacao')::uuid, 'ritmo-avaliacao', (select id from public.lessons where slug = 'ritmo-e-pulsacao'), 'Avaliação: padrões com colcheias', 'Reproduza os padrões tocando no botão.', 'rhythm_tap', '{"rounds":5,"patterns":["q e e q q","e e q h","q q e e q","h e e q","q e e e e q"],"bpm":76}'::jsonb, 'ritmo-pulsacao', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:acordes-basicos')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'acordes-basicos', 'Reconhecimento de acordes básicos', 'Maior, menor e as notas extremas de um acorde.', 5, 2, 25, '{"objetivo":"Distinguir acordes maiores e menores, ouvir a nota mais grave e a mais aguda de um acorde e reconhecer consonância e dissonância.","explicacao":[{"type":"p","text":"Um acorde é a combinação de três ou mais notas soando juntas. A tríade básica tem fundamental, terça e quinta. O que muda entre maior e menor é a terça: maior (4 semitons acima da fundamental) ou menor (3 semitons)."},{"type":"p","text":"Em grupo, cada voz canta uma nota do acorde. Saber ouvir a nota mais grave (geralmente o baixo) e a mais aguda (geralmente a melodia) ajuda você a se localizar: “minha nota está no meio, acima do baixo”."},{"type":"list","items":["Consonâncias: soam estáveis (oitava, quinta, terças, sextas).","Dissonâncias: soam tensas e pedem resolução (segundas, sétimas, trítono).","Dissonância não é erro: ela cria movimento. Mas uma dissonância fora do lugar indica que alguém saiu da própria nota."]}],"demonstracao":[{"type":"chords","root":"C4","qualities":["maior","menor"]},{"type":"audio","label":"Acorde de Dó maior com as notas separadas","notes":["C4","E4","G4",["C4","E4","G4"]],"tempo":70},{"type":"intervals","root":"C4","semitones":[2,4,7,11]}],"exercicioGuiado":{"passos":["Toque Dó maior e Dó menor alternadamente e perceba a diferença da terça.","Ouça o acorde arpejado e cante cada nota: fundamental, terça e quinta.","Ouça o acorde em bloco e cante só a nota mais grave; depois só a mais aguda.","Faça a prática de maior/menor e a avaliação de notas extremas."]},"pratiqueSozinho":{"passos":["Laboratório de acordes no nível recomendado.","Laboratório de consonância e dissonância."],"minutos":8,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Achar que acorde menor é “triste” sempre.","correcao":"O caráter depende do contexto; use a terça como referência, não a emoção."},{"erro":"Perder a nota grave quando o acorde é longo.","correcao":"Cante baixinho a nota que você acha que é a mais grave enquanto o acorde soa."}],"seguranca":["Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações de tipo de acorde e de nota extrema."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
