insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:acordes-maior-menor-avaliacao')::uuid, 'acordes-maior-menor-avaliacao', (select id from public.lessons where slug = 'acordes-basicos'), 'Avaliação: maior ou menor?', 'Ouça o acorde arpejado e em bloco.', 'chord_quality', '{"rounds":8,"qualities":["maior","menor"],"play":"ambos"}'::jsonb, 'acordes', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:acordes-extremos-avaliacao')::uuid, 'acordes-extremos-avaliacao', (select id from public.lessons where slug = 'acordes-basicos'), 'Avaliação: a nota mais grave', 'Ouça o acorde e escolha qual opção é a nota mais grave dele.', 'chord_extreme', '{"rounds":6,"ask":"grave","size":3}'::jsonb, 'acordes', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:consonancia-pratica')::uuid, 'consonancia-pratica', (select id from public.lessons where slug = 'acordes-basicos'), 'Prática: consonante ou dissonante?', 'Ouça as duas notas juntas.', 'consonance', '{"rounds":8}'::jsonb, 'consonancia', 'pratica', 2, 2) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:canto-em-conjunto')::uuid, 'canto-em-conjunto', 'C', 'Canto em conjunto', 'Do uníssono à escuta ativa', 'Antes de dividir vozes, o grupo aprende a soar como um só: mesma altura, mesmo ritmo, entradas e cortes juntos, equilíbrio e escuta. A trilha termina com o desafio de manter a própria linha enquanto outras melodias soam.', 'users', 2) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:unissono')::uuid, (select id from public.learning_paths where slug = 'canto-em-conjunto'), 'unissono', 'Uníssono', 'Cantar a mesma melodia como uma só voz.', 0, 1, 20, '{"objetivo":"Cantar a mesma melodia com unidade de altura, ritmo, respiração, dicção e finalização.","explicacao":[{"type":"p","text":"Uníssono é quando todos cantam a mesma melodia. Parece simples, mas é um dos maiores desafios de um grupo: cada pessoa tem um timbre, um volume e um jeito de pronunciar. O objetivo é que o resultado soe como uma única voz bem afinada."},{"type":"list","items":["Mesma altura: ouça quem está ao seu lado e ajuste-se ao som do grupo, não o contrário.","Mesmo ritmo: as sílabas começam juntas. Siga o regente, não a pessoa mais rápida.","Respirações planejadas: todos respiram no mesmo lugar, salvo respiração escalonada combinada.","Mesma vogal: combinem o formato da boca nas vogais longas.","Finalização conjunta: o corte (fim da nota e consoante final) acontece no gesto do regente."]},{"type":"p","text":"Quando homens e mulheres cantam “em uníssono”, na verdade cantam em oitavas: a mesma melodia, os homens uma oitava abaixo. Isso também é uníssono no sentido musical do grupo."},{"type":"tip","title":"Volume a serviço do grupo","text":"Se você só ouve a sua própria voz, provavelmente está cantando forte demais. Se não ouve nada da sua voz, talvez esteja fraco demais. O ponto certo é ouvir a si e aos vizinhos."}],"demonstracao":[{"type":"audio","label":"Mesma melodia em oitavas (vozes femininas e masculinas)","notes":[["E4","E3"],["E4","E3"],["F4","F3"],["G4","G3"]],"tempo":90},{"type":"harmonyLink","arrangement":"hino-alegria-unissono","label":"Praticar o “Hino da Alegria” em uníssono no treinador"}],"exercicioGuiado":{"passos":["No treinador, escolha “Hino da Alegria — uníssono” e ouça a melodia no modo solo.","Cante junto com a referência em “lu”, depois com o texto.","Marque na letra onde respirar (fim de cada linha) e respeite esse plano.","Pratique a finalização: a última nota termina exatamente no tempo 4 do último compasso.","No ensaio, cante com o grupo ouvindo os vizinhos."]},"pratiqueSozinho":{"passos":["Treinador de harmonia: uníssono, 3 repetições.","Grave-se cantando junto com a referência e confira se as sílabas começam juntas."],"minutos":8,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Cantar mais forte que o grupo para “ajudar”.","correcao":"No uníssono, quem se destaca quebra a unidade. Ajude ouvindo e se ajustando."},{"erro":"Cada um terminar a nota num momento.","correcao":"O corte é um gesto do regente; olhe para ele nas finalizações."},{"erro":"Vogais diferentes nas notas longas.","correcao":"Combinem a vogal e o formato da boca."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e cantar o uníssono no treinador do início ao fim."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'canto-unissono' from public.lessons where slug = 'unissono' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:unissono-pratica-treinador')::uuid, 'unissono-pratica-treinador', (select id from public.lessons where slug = 'unissono'), 'Prática no treinador de harmonia', 'Cante o Hino da Alegria em uníssono e avalie.', 'harmony_part', '{"voices":1,"arrangementSlug":"hino-alegria-unissono"}'::jsonb, 'canto-unissono', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:unissono-avaliacao')::uuid, 'unissono-avaliacao', (select id from public.lessons where slug = 'unissono'), 'Avaliação: princípios do uníssono', 'Responda sobre canto em uníssono.', 'quiz', '{"questions":[{"q":"Homens e mulheres cantando a mesma melodia, os homens uma oitava abaixo, estão…","options":["Em uníssono (oitavas)","Em duas vozes diferentes","Desafinados","Em terças"],"answer":0},{"q":"Se você só ouve a sua própria voz no grupo, provavelmente…","options":["Está cantando forte demais","Está cantando perfeitamente","Precisa cantar mais forte","Está fora do ritmo"],"answer":0},{"q":"Quem define o momento da finalização?","options":["O regente, com o gesto de corte","Quem canta mais alto","Cada pessoa","O instrumentista"],"answer":0},{"q":"Para unificar o som nas notas longas, o naipe deve combinar…","options":["A vogal e o formato da boca","O volume máximo","A posição dos pés","A cor da roupa"],"answer":0},{"q":"Ouça: as duas notas formam uníssono (a mesma nota) ou não?","options":["Uníssono","Notas diferentes"],"answer":0,"audio":{"notes":[["G4","G4"]],"mode":"chord","tempo":40}}]}'::jsonb, 'canto-unissono', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:entradas-e-finalizacoes')::uuid, (select id from public.learning_paths where slug = 'canto-em-conjunto'), 'entradas-e-finalizacoes', 'Entradas e finalizações', 'Começar e terminar juntos, no tempo certo.', 1, 1, 15, '{"objetivo":"Entrar no tempo exato após pausas e contagens e finalizar as notas juntos, respeitando a duração escrita.","explicacao":[{"type":"p","text":"A entrada é um dos momentos mais expostos do canto em grupo. Uma entrada segura nasce de três coisas: contar o tempo durante a pausa, respirar no tempo anterior à entrada e já “ouvir por dentro” a primeira nota."},{"type":"list","items":["Respire no tempo anterior à entrada, no andamento da música — não antes, não depois.","Durante pausas, conte mentalmente: “1, 2, 3, 4”.","A primeira nota precisa estar pronta na mente (pergunte ao instrumentista ou use a nota de referência).","Finalização: a nota longa dura até o tempo indicado. Uma mínima no tempo 3 termina no começo do próximo compasso, não antes."]}],"demonstracao":[{"type":"rhythm","pattern":"rq q q q","bpm":80,"label":"Entrada após pausa de um tempo"},{"type":"rhythm","pattern":"rh q q","bpm":80,"label":"Entrada após pausa de dois tempos"},{"type":"rhythm","pattern":"q q h","bpm":80,"label":"Finalização em mínima (dura até o fim do compasso)"}],"exercicioGuiado":{"passos":["Com o metrônomo a 80 bpm, conte em voz alta “1, 2, 3, 4” e bata palma apenas no tempo 2.","Agora inspire no tempo 1 e cante “lá” no tempo 2, sustentando até o tempo 4.","Faça o mesmo entrando no tempo 3.","Pratique os padrões da demonstração no exercício de ritmo."]},"pratiqueSozinho":{"passos":["Exercício de entradas (5 minutos).","Em um hino conhecido, conte as pausas entre as frases em voz baixa."],"minutos":6,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Respirar cedo demais e prender o ar até a entrada.","correcao":"A respiração faz parte do ritmo: inspire no tempo anterior."},{"erro":"Encurtar a última nota.","correcao":"Conte até o fim; a finalização é tão importante quanto a entrada."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo."],"criterioAvanco":"Acertar pelo menos 70% na avaliação de entradas após pausas."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
