insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:entradas-avaliacao')::uuid, 'entradas-avaliacao', (select id from public.lessons where slug = 'entradas-e-finalizacoes'), 'Avaliação: entradas após pausas', 'Ouça a contagem; toque somente onde há nota (as pausas ficam em silêncio).', 'rhythm_tap', '{"rounds":5,"patterns":["rq q q q","rh q q","rq q h","q rq q q","rh h"],"bpm":80,"toleranceMs":140}'::jsonb, 'ritmo-pulsacao', 'avaliacao', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:finalizacoes-avaliacao')::uuid, 'finalizacoes-avaliacao', (select id from public.lessons where slug = 'entradas-e-finalizacoes'), 'Avaliação: duração das finalizações', 'Responda sobre entradas e finalizações.', 'quiz', '{"questions":[{"q":"Em 4/4, uma mínima que começa no tempo 3 termina…","options":["No início do próximo compasso","No tempo 4","No tempo 3 e meio","Quando faltar ar"],"answer":0},{"q":"Quando respirar para uma entrada no tempo 2?","options":["No tempo 1, no andamento da música","Dois compassos antes","Durante o tempo 2","Não é preciso respirar"],"answer":0},{"q":"O que fazer durante uma pausa longa?","options":["Contar os tempos mentalmente","Conversar com o vizinho","Esperar o vizinho começar","Cantar baixinho"],"answer":0}]}'::jsonb, 'canto-unissono', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:equilibrio-sonoro')::uuid, (select id from public.learning_paths where slug = 'canto-em-conjunto'), 'equilibrio-sonoro', 'Equilíbrio sonoro', 'Nenhuma voz sobrando, nenhuma faltando.', 2, 2, 15, '{"objetivo":"Compreender o equilíbrio entre naipes e entre vozes do mesmo naipe, e ajustar a própria intensidade ao conjunto.","explicacao":[{"type":"p","text":"Equilíbrio é a proporção de volume entre as vozes. Em geral, a melodia precisa ser ouvida com clareza, o baixo sustenta a harmonia e as vozes intermediárias preenchem o acorde sem encobrir a melodia. Num naipe, nenhuma voz individual deve se destacar."},{"type":"list","items":["Naipe com mais pessoas canta mais suave; naipe com poucas pessoas pode precisar de mais presença.","Notas agudas tendem a soar mais fortes: sopranos e tenores precisam cuidar do volume nos agudos.","Na dúvida, siga a pirâmide sonora: baixo mais presente, agudos mais leves.","Microfones mudam tudo: em grupos amplificados, combine o equilíbrio com quem opera o som."]},{"type":"tip","title":"Teste da vizinhança","text":"Você deve ouvir as pessoas ao seu lado. Se não ouve, reduza seu volume até ouvi-las."}],"demonstracao":[{"type":"harmonyLink","arrangement":"hino-alegria-satb","label":"No treinador, ajuste o volume de cada naipe e ouça o efeito no equilíbrio"},{"type":"audio","label":"Acorde equilibrado (todas as vozes com o mesmo volume)","notes":[["C3","G3","C4","E4"]],"mode":"chord","tempo":30}],"exercicioGuiado":{"passos":["Abra o “Hino da Alegria — SATB” no modo conjunto.","Reduza o volume do soprano e ouça como a melodia “some”. Volte ao normal.","Aumente apenas o contralto e perceba como o acorde fica desequilibrado.","Encontre uma combinação em que a melodia é clara e o acorde soa cheio."]},"pratiqueSozinho":{"passos":["Repita o experimento de volumes com outro arranjo.","No próximo ensaio, aplique o teste da vizinhança."],"minutos":5,"frequencia":"1 vez por semana"},"errosComuns":[{"erro":"Achar que cantar mais forte é ajudar o naipe.","correcao":"Ajudar é ser ouvido junto, não por cima."},{"erro":"Ignorar o equilíbrio nos agudos.","correcao":"Notas agudas projetam mais: alivie o volume."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes."],"criterioAvanco":"Acertar pelo menos 70% da avaliação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'escuta-ativa' from public.lessons where slug = 'equilibrio-sonoro' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:equilibrio-avaliacao')::uuid, 'equilibrio-avaliacao', (select id from public.lessons where slug = 'equilibrio-sonoro'), 'Avaliação: equilíbrio sonoro', 'Responda sobre equilíbrio entre vozes.', 'quiz', '{"questions":[{"q":"Qual voz geralmente precisa ser ouvida com clareza?","options":["A melodia","A voz mais grave sempre","A voz de quem canta mais alto","Nenhuma"],"answer":0},{"q":"Notas agudas tendem a…","options":["Soar mais fortes e precisar de cuidado com o volume","Soar mais fracas","Não interferir no equilíbrio","Ser sempre desafinadas"],"answer":0},{"q":"Um naipe com muitas pessoas deve…","options":["Cantar mais suave para não encobrir os outros","Cantar mais forte","Cantar sempre a melodia","Diminuir apenas no final"],"answer":0},{"q":"No teste da vizinhança, se você não ouve quem está ao lado…","options":["Reduza seu volume","Aumente seu volume","Troque de lugar","Pare de cantar"],"answer":0}]}'::jsonb, 'escuta-ativa', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:escuta-ativa')::uuid, (select id from public.learning_paths where slug = 'canto-em-conjunto'), 'escuta-ativa', 'Escuta ativa', 'Ouvir o conjunto enquanto canta: entradas, vozes e frases.', 3, 2, 20, '{"objetivo":"Perceber quantas vozes estão soando, qual voz entrou, e comparar frases melódicas — habilidades de quem canta ouvindo o grupo.","explicacao":[{"type":"p","text":"Escuta ativa é cantar com os ouvidos abertos para o conjunto. Quem só ouve a si mesmo não percebe quando o grupo desafina, acelera ou quando outra voz entra. Quem ouve o conjunto se ajusta em tempo real."},{"type":"list","items":["Perceba as entradas: em muitos arranjos as vozes entram em momentos diferentes.","Identifique sua posição no acorde: acima do baixo? abaixo da melodia?","Compare frases: o refrão volta igual ou com alguma mudança?"]}],"demonstracao":[{"type":"harmonyLink","arrangement":"canone-solfejo","label":"Ouça o cânone: as vozes entram uma de cada vez"}],"exercicioGuiado":{"passos":["Ouça o cânone no modo conjunto e conte quantas vozes entram.","Ouça de novo acompanhando apenas a 2ª voz do início ao fim.","Faça o exercício de entradas e o de comparação de frases."]},"pratiqueSozinho":{"passos":["Laboratório: entradas vocais e frases (5 minutos).","Ouça uma gravação coral e tente seguir uma voz interna."],"minutos":7,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Prestar atenção só na melodia.","correcao":"Escolha uma voz interna e siga-a do início ao fim."}],"seguranca":["Use volume moderado nos fones de ouvido."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações de entradas e frases."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
