insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:escuta-entradas-avaliacao')::uuid, 'escuta-entradas-avaliacao', (select id from public.lessons where slug = 'escuta-ativa'), 'Avaliação: quantas vozes entraram?', 'As vozes entram uma de cada vez e continuam soando.', 'entry_detect', '{"rounds":6,"maxVoices":3,"ask":"quantidade"}'::jsonb, 'escuta-ativa', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:escuta-frases-avaliacao')::uuid, 'escuta-frases-avaliacao', (select id from public.lessons where slug = 'escuta-ativa'), 'Avaliação: frases iguais ou diferentes', 'Compare as duas frases melódicas.', 'phrase_compare', '{"rounds":6,"length":4}'::jsonb, 'memoria-melodica', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:manter-a-propria-linha')::uuid, (select id from public.learning_paths where slug = 'canto-em-conjunto'), 'manter-a-propria-linha', 'Manutenção da própria linha vocal', 'Sustentar a sua nota enquanto outras vozes cantam melodias diferentes.', 4, 2, 25, '{"objetivo":"Sustentar uma nota ou uma linha própria enquanto outra melodia soa, sem ser “arrastado” por ela.","explicacao":[{"type":"p","text":"O momento mais difícil para quem começa a cantar em vozes é quando outra voz faz uma melodia diferente: a tendência é seguir a melodia mais forte (normalmente a principal) e abandonar a própria. Isso se treina com passos pequenos."},{"type":"list","ordered":true,"items":["Primeiro, sustente uma única nota enquanto outra melodia se move.","Depois, cante uma linha curta com notas repetidas contra uma melodia em movimento.","Depois, cante sua linha completa com a melodia em volume baixo (modo guiado).","Por fim, cante com todas as vozes no mesmo volume (modo conjunto)."]},{"type":"tip","title":"Âncoras","text":"Marque na sua parte as notas “âncora”: notas longas ou repetidas que você conhece bem. Quando se perder, volte para a próxima âncora."},{"type":"warning","text":"Para usar o microfone neste exercício, use fones de ouvido: assim o microfone capta somente a sua voz e não a melodia de referência."}],"demonstracao":[{"type":"harmonyLink","arrangement":"pedal-e-melodia","label":"Exercício “Nota pedal e melodia”: sustente a nota enquanto a melodia se move"},{"type":"toolLink","tool":"afinador","label":"Treinador de afinação (use fones)"}],"exercicioGuiado":{"passos":["Abra “Nota pedal e melodia” no treinador, escolha a voz do pedal e o modo guiado.","Cante o pedal com a melodia em volume baixo; aumente o volume da melodia aos poucos.","Faça o exercício de sustentação com distração abaixo (com fones, se usar o microfone).","Passe para o exercício “Terças paralelas” cantando a voz de baixo."]},"pratiqueSozinho":{"passos":["3 repetições do pedal com a melodia em volume normal.","Exercício de sustentação com distração (3 notas)."],"minutos":10,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Seguir a melodia quando ela se aproxima da sua nota.","correcao":"Pense na sua nota com antecedência e mantenha-a firme, em volume moderado."},{"erro":"Tampar um ouvido para não ouvir a outra voz.","correcao":"É útil no início, mas o objetivo é cantar ouvindo o conjunto."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Média de pelo menos 70% na sustentação da própria nota com outra melodia soando."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
