insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:linha-propria-pedal')::uuid, 'linha-propria-pedal', (select id from public.lessons where slug = 'manter-a-propria-linha'), 'Prática: pedal no treinador', 'Cante a voz do pedal no exercício “Nota pedal e melodia”.', 'harmony_part', '{"voices":2,"arrangementSlug":"pedal-e-melodia"}'::jsonb, 'independencia-vocal', 'pratica', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:linha-propria-avaliacao')::uuid, 'linha-propria-avaliacao', (select id from public.lessons where slug = 'manter-a-propria-linha'), 'Avaliação: sustente a sua nota com distração', 'Sustente a nota enquanto outra melodia toca. Com microfone, use fones de ouvido.', 'sing_note', '{"rounds":3,"holdSeconds":4,"toleranceCents":30,"distractor":true}'::jsonb, 'independencia-vocal', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:harmonia-vocal')::uuid, 'harmonia-vocal', 'D', 'Harmonia vocal', 'De duas a quatro vozes, com independência', 'O coração da formação: cantar uma linha própria mantendo afinação, ritmo e equilíbrio com as outras vozes. Progride de duas vozes em terças e sextas até acordes a quatro vozes, quarteto masculino e arranjos com contracanto e pedal.', 'git-merge', 3) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:duas-vozes')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'duas-vozes', 'Duas vozes', 'Melodia principal e segunda voz; movimento paralelo e contrário.', 0, 2, 25, '{"objetivo":"Cantar uma segunda voz contra a melodia principal, reconhecendo movimento paralelo, contrário e nota sustentada contra melodia em movimento.","explicacao":[{"type":"p","text":"Na harmonia a duas vozes, uma voz canta a melodia principal e a outra canta uma linha de apoio — a “segunda voz”. A segunda voz não é uma melodia qualquer: ela se relaciona com a principal por intervalos consonantes, principalmente terças e sextas."},{"type":"list","items":["Movimento paralelo: as duas vozes sobem e descem juntas, mantendo o mesmo intervalo (ex.: terças paralelas).","Movimento contrário: uma voz sobe enquanto a outra desce. Dá independência e riqueza.","Movimento oblíquo: uma voz fica parada (nota sustentada) enquanto a outra se move."]},{"type":"tip","title":"Como não ser arrastado pela melodia","text":"Aprenda a sua voz sozinho(a) primeiro (modo solo), depois com a melodia baixinha (modo guiado) e só então com as duas no mesmo volume (modo conjunto). Nos momentos de movimento contrário, pense na direção da SUA linha."}],"demonstracao":[{"type":"harmonyLink","arrangement":"movimento-contrario","label":"Exercício: movimento contrário"},{"type":"harmonyLink","arrangement":"hino-alegria-duas-vozes","label":"Hino da Alegria a duas vozes"},{"type":"audio","label":"Terça e sexta soando juntas","notes":[["C4","E4"],["E3","C4"]],"tempo":40}],"exercicioGuiado":{"passos":["Abra “Movimento contrário” e ouça as duas vozes no modo conjunto.","Escolha a voz 2 e cante no modo solo até conhecê-la bem.","Passe para o modo guiado: a voz 1 soa baixinho enquanto você canta a 2.","Abra o “Hino da Alegria a duas vozes” e repita o processo com a segunda voz.","Grave-se no modo conjunto e ouça: a sua voz se manteve?"]},"pratiqueSozinho":{"passos":["Treinador: segunda voz do Hino da Alegria (modo guiado → conjunto).","Marque os compassos difíceis e repita só esses trechos."],"minutos":12,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Passar para a melodia sem perceber.","correcao":"Cante a sua linha em volume confortável e use as notas-âncora."},{"erro":"Cantar a segunda voz mais forte que a melodia.","correcao":"A melodia lidera; a segunda voz apoia."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e cantar a segunda voz do Hino da Alegria no modo conjunto."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
