insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:duas-vozes-treinador')::uuid, 'duas-vozes-treinador', (select id from public.lessons where slug = 'duas-vozes'), 'Prática: segunda voz no treinador', 'Cante a segunda voz do Hino da Alegria e avalie.', 'harmony_part', '{"voices":2,"arrangementSlug":"hino-alegria-duas-vozes"}'::jsonb, 'harmonia-duas-vozes', 'pratica', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:duas-vozes-avaliacao')::uuid, 'duas-vozes-avaliacao', (select id from public.lessons where slug = 'duas-vozes'), 'Avaliação: movimentos entre vozes', 'Responda e ouça os exemplos.', 'quiz', '{"questions":[{"q":"Duas vozes que sobem e descem juntas mantendo o intervalo estão em movimento…","options":["Paralelo","Contrário","Oblíquo","Uníssono"],"answer":0},{"q":"Uma voz sobe enquanto a outra desce. Que movimento é esse?","options":["Contrário","Paralelo","Oblíquo","Direto"],"answer":0},{"q":"Uma voz sustenta a nota enquanto a outra se move:","options":["Movimento oblíquo","Movimento paralelo","Movimento contrário","Cânone"],"answer":0},{"q":"Ouça: a voz aguda sobe e a grave desce. Que movimento você ouviu?","options":["Contrário","Paralelo"],"answer":0,"audio":{"notes":[["E4","C4"],["F4","A3"],["G4","G3"]],"mode":"seq","tempo":70}},{"q":"Qual é a sequência recomendada para aprender a sua voz?","options":["Solo → guiado → conjunto","Conjunto → solo","Só conjunto","Só ler a partitura"],"answer":0}]}'::jsonb, 'harmonia-duas-vozes', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:tercas-e-sextas')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'tercas-e-sextas', 'Terças e sextas', 'Os intervalos mais usados entre duas vozes.', 1, 2, 25, '{"objetivo":"Cantar terças e sextas paralelas com afinação e reconhecer esses intervalos entre duas vozes.","explicacao":[{"type":"p","text":"Terças e sextas são consonâncias imperfeitas: soam doces, cheias e permitem movimento paralelo sem perder a independência. Por isso a maioria das segundas vozes do louvor congregacional caminha em terças ou sextas da melodia."},{"type":"list","items":["Terça abaixo da melodia: a segunda voz canta duas notas da escala abaixo (Mi → Dó, Fá → Ré).","Sexta abaixo: a segunda voz canta cinco notas da escala abaixo (Dó → Mi, Ré → Fá).","Terça e sexta se complementam: uma terça invertida (nota de baixo uma oitava acima) vira sexta.","Quinta e oitava paralelas soam “ocas” e fazem as vozes perderem independência; evite-as na segunda voz."]},{"type":"tip","title":"Afinação de terças","text":"A terça maior bem afinada num acorde soa um pouco mais baixa que a do teclado. Ouça o grupo: quando a terça “encaixa”, o acorde parece vibrar."}],"demonstracao":[{"type":"harmonyLink","arrangement":"tercas-paralelas","label":"Terças paralelas"},{"type":"harmonyLink","arrangement":"sextas-paralelas","label":"Sextas paralelas"},{"type":"intervals","root":"C4","semitones":[3,4,8,9]}],"exercicioGuiado":{"passos":["Abra “Terças paralelas”, escolha a voz 2 e cante no modo solo.","Modo guiado e depois conjunto, gravando uma vez.","Repita com “Sextas paralelas”.","Faça a avaliação de reconhecimento de terças e sextas."]},"pratiqueSozinho":{"passos":["Cante a escala de Dó em terças com o teclado (Dó–Mi, Ré–Fá, Mi–Sol…).","Treinador: terças e sextas paralelas no modo conjunto."],"minutos":10,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Cantar sempre a mesma distância em semitons.","correcao":"Na escala, as terças alternam entre maiores e menores. Siga as notas, não um número fixo de semitons."},{"erro":"Escorregar para a quinta.","correcao":"Ouça o intervalo: a quinta soa mais aberta e “oca”."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes."],"criterioAvanco":"Acertar pelo menos 70% na avaliação de terças e sextas."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
