insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:tercas-treinador')::uuid, 'tercas-treinador', (select id from public.lessons where slug = 'tercas-e-sextas'), 'Prática: terças paralelas', 'Cante a voz 2 de “Terças paralelas”.', 'harmony_part', '{"voices":2,"arrangementSlug":"tercas-paralelas"}'::jsonb, 'harmonia-duas-vozes', 'pratica', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:tercas-sextas-avaliacao')::uuid, 'tercas-sextas-avaliacao', (select id from public.lessons where slug = 'tercas-e-sextas'), 'Avaliação: terça ou sexta?', 'Identifique o intervalo harmônico.', 'interval_id', '{"rounds":10,"intervals":[3,4,8,9],"direction":"harmonic"}'::jsonb, 'intervalos', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:tres-vozes')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'tres-vozes', 'Três vozes', 'Acordes, função de cada linha e entradas em momentos diferentes.', 2, 2, 30, '{"objetivo":"Cantar a sua linha numa textura de três vozes, compreendendo a distribuição das notas do acorde, notas comuns e entradas independentes.","explicacao":[{"type":"p","text":"Com três vozes já é possível cantar acordes completos: uma voz para cada nota da tríade (fundamental, terça e quinta). Normalmente a voz mais aguda canta a melodia, a mais grave dá a base, e a do meio completa o acorde."},{"type":"list","items":["Notas comuns: quando dois acordes vizinhos têm uma nota em comum, a voz que canta essa nota costuma permanecer nela. Isso facilita a afinação.","Condução de vozes: cada voz se move pelo menor caminho possível para a próxima nota do acorde.","Independência rítmica: em cânones e arranjos com imitação, as vozes entram em momentos diferentes.","Equilíbrio: a voz do meio é a mais difícil de ouvir; ela precisa estar presente sem encobrir a melodia."]}],"demonstracao":[{"type":"harmonyLink","arrangement":"triades-tres-vozes","label":"Tríades a três vozes (I – vi – IV – V – I)"},{"type":"harmonyLink","arrangement":"canone-solfejo","label":"Cânone do solfejo: entradas em momentos diferentes"},{"type":"harmonyLink","arrangement":"hino-alegria-tres-vozes","label":"Hino da Alegria a três vozes"}],"exercicioGuiado":{"passos":["Em “Tríades a três vozes”, cante cada uma das três vozes no modo solo e perceba quais notas permanecem iguais entre os acordes.","Escolha a voz mais adequada à sua região e cante no modo guiado e no conjunto.","No cânone, cante a voz 2: você entra depois da voz 1 com a mesma melodia.","Cante a sua voz no Hino da Alegria a três vozes."]},"pratiqueSozinho":{"passos":["Treinador: Hino da Alegria a três vozes (sua voz).","Cânone do solfejo entrando como voz 2 ou 3."],"minutos":12,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Abandonar a nota comum entre acordes.","correcao":"Se a nota se repete, permaneça nela com segurança."},{"erro":"Esperar a outra voz para entrar.","correcao":"Conte os tempos: a sua entrada tem um momento próprio."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e cantar a sua voz a três vozes no modo conjunto."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
