insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:tres-vozes-acordes-avaliacao')::uuid, 'tres-vozes-acordes-avaliacao', (select id from public.lessons where slug = 'tres-vozes'), 'Avaliação: a nota mais aguda do acorde', 'Ouça o acorde de três notas e encontre a nota mais aguda.', 'chord_extreme', '{"rounds":6,"ask":"aguda","size":3}'::jsonb, 'acordes', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:tres-vozes-avaliacao')::uuid, 'tres-vozes-avaliacao', (select id from public.lessons where slug = 'tres-vozes'), 'Avaliação: conceitos de três vozes', 'Responda sobre harmonia a três vozes.', 'quiz', '{"questions":[{"q":"Uma tríade é formada por…","options":["Fundamental, terça e quinta","Três fundamentais","Fundamental, segunda e quarta","Três notas quaisquer"],"answer":0},{"q":"Quando dois acordes vizinhos têm uma nota em comum, a voz que a canta geralmente…","options":["Permanece na mesma nota","Salta uma oitava","Faz uma pausa","Canta mais forte"],"answer":0},{"q":"Qual voz costuma ser a mais difícil de ouvir numa textura a três vozes?","options":["A voz do meio","A melodia","O baixo","Nenhuma"],"answer":0},{"q":"Em um cânone, as vozes…","options":["Cantam a mesma melodia entrando em momentos diferentes","Cantam melodias diferentes ao mesmo tempo, começando juntas","Cantam em uníssono","Não têm letra"],"answer":0}]}'::jsonb, 'harmonia-tres-quatro-vozes', 'avaliacao', 2, 2) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:acordes-a-quatro-vozes')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'acordes-a-quatro-vozes', 'Acordes a quatro vozes (SATB)', 'Soprano, contralto, tenor e baixo: formação, condução e estudo da própria parte.', 3, 3, 30, '{"objetivo":"Compreender a formação tradicional SATB, como os acordes são distribuídos em quatro vozes e como estudar a própria parte ouvindo o conjunto.","explicacao":[{"type":"p","text":"A formação SATB (Soprano, Contralto — em inglês Alto —, Tenor e Baixo) é a base dos hinários. Como uma tríade tem três notas, numa harmonia a quatro vozes uma nota é dobrada (geralmente a fundamental)."},{"type":"list","items":["Soprano: normalmente canta a melodia.","Contralto: voz feminina intermediária, logo abaixo do soprano.","Tenor: voz masculina aguda; em partituras, é escrito na clave de Sol uma oitava acima do que soa (ou na clave de Fá).","Baixo: voz masculina grave; costuma cantar a fundamental do acorde e define a harmonia.","Regras de ouro da condução: mover cada voz pelo menor caminho, manter notas comuns, evitar quintas e oitavas paralelas e não cruzar vozes sem motivo."]},{"type":"tip","title":"Como estudar a sua parte","text":"1) Leia o texto e o ritmo. 2) Ouça a sua voz no modo solo. 3) Cante com a sua voz destacada (guiado). 4) Cante no conjunto. 5) Marque e repita os compassos difíceis. 6) Volte para o conjunto ouvindo quem está acima e abaixo de você."}],"demonstracao":[{"type":"harmonyLink","arrangement":"acordes-sustentados-satb","label":"Acordes sustentados SATB (para afinação vertical)"},{"type":"harmonyLink","arrangement":"hino-alegria-satb","label":"Hino da Alegria a quatro vozes (SATB)"},{"type":"audio","label":"Acorde de Dó maior a quatro vozes (Dó3–Sol3–Dó4–Mi4)","notes":[["C3","G3","C4","E4"]],"mode":"chord","tempo":30}],"exercicioGuiado":{"passos":["Abra o Hino da Alegria SATB no modo conjunto e ouça inteiro.","Escolha a sua voz e siga os passos de estudo: solo, guiado, conjunto.","Marque os compassos difíceis e use a repetição de trecho.","Nos acordes sustentados, cante a sua nota e ouça o acorde completo se formar."]},"pratiqueSozinho":{"passos":["Treinador: sua voz no Hino da Alegria SATB.","Acordes sustentados SATB no modo conjunto."],"minutos":15,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Tenores lendo a clave de Sol na altura escrita.","correcao":"Na clave de Sol com o 8 embaixo, o tenor soa uma oitava abaixo do escrito."},{"erro":"Baixos fugindo da fundamental por insegurança.","correcao":"A nota do baixo define o acorde: estude-a com prioridade e firmeza."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e cantar a sua parte no Hino da Alegria SATB no modo conjunto."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
