insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:satb-treinador')::uuid, 'satb-treinador', (select id from public.lessons where slug = 'acordes-a-quatro-vozes'), 'Prática: sua parte no SATB', 'Cante a sua parte no Hino da Alegria SATB e avalie.', 'harmony_part', '{"voices":4,"arrangementSlug":"hino-alegria-satb"}'::jsonb, 'harmonia-tres-quatro-vozes', 'pratica', 3, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:satb-avaliacao')::uuid, 'satb-avaliacao', (select id from public.lessons where slug = 'acordes-a-quatro-vozes'), 'Avaliação: formação SATB', 'Responda sobre a escrita a quatro vozes.', 'quiz', '{"questions":[{"q":"Em SATB, quem normalmente canta a melodia?","options":["Soprano","Contralto","Tenor","Baixo"],"answer":0},{"q":"Numa tríade a quatro vozes, qual nota costuma ser dobrada?","options":["A fundamental","A terça","A quinta","Nenhuma"],"answer":0},{"q":"O tenor escrito na clave de Sol com um 8 embaixo soa…","options":["Uma oitava abaixo do escrito","Uma oitava acima","Exatamente como escrito","Uma quinta abaixo"],"answer":0},{"q":"Qual destas é uma regra de condução de vozes?","options":["Evitar quintas e oitavas paralelas","Sempre saltar uma oitava","Cruzar as vozes em todos os acordes","Mudar todas as notas a cada acorde"],"answer":0},{"q":"Ouça o acorde. Qual nota está no baixo?","options":["Dó","Mi","Sol"],"answer":0,"audio":{"notes":[["C3","G3","E4","C5"]],"mode":"chord","tempo":30}}]}'::jsonb, 'harmonia-tres-quatro-vozes', 'avaliacao', 3, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:quarteto-masculino')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'quarteto-masculino', 'Quarteto masculino', 'Primeiro tenor, segundo tenor, barítono e baixo.', 4, 3, 25, '{"objetivo":"Conhecer a formação TTBB, a função de cada voz e cantar uma parte num quarteto masculino.","explicacao":[{"type":"p","text":"No quarteto masculino (TTBB), as quatro vozes ficam numa região mais próxima, o que produz um som muito unido — e exige afinação cuidadosa. A nomenclatura e a distribuição variam conforme o arranjo e a tradição (hinódia, gospel, barbershop)."},{"type":"list","items":["Primeiro tenor: a voz mais aguda; frequentemente canta acima da melodia, com voz leve.","Segundo tenor: em muitos arranjos (como no estilo barbershop, onde é chamado de “lead”) canta a melodia.","Barítono: completa o acorde; às vezes canta acima, às vezes abaixo da melodia — é a voz que mais “cruza”.","Baixo: a fundamental e o alicerce rítmico."]},{"type":"p","text":"Neste arranjo de treino (melodia NEW BRITAIN, conhecida como “Amazing Grace”, de domínio público, com texto original da plataforma), a melodia está no segundo tenor. Repare nos momentos em que o barítono canta acima da melodia."}],"demonstracao":[{"type":"harmonyLink","arrangement":"que-grande-amor-ttbb","label":"“Que grande amor” — quarteto masculino"},{"type":"audio","label":"Acorde de Sol maior em quarteto (Sol2–Ré3–Sol3–Si3)","notes":[["G2","D3","G3","B3"]],"mode":"chord","tempo":30}],"exercicioGuiado":{"passos":["Ouça o arranjo no modo conjunto e acompanhe a melodia no segundo tenor.","Escolha a sua voz pela região confortável (consulte sua classificação provisória).","Estude no modo solo e guiado; marque os trechos em que a sua voz cruza com outra.","Cante no modo conjunto e grave."]},"pratiqueSozinho":{"passos":["Treinador: sua voz em “Que grande amor”.","Afinação vertical: sustente o acorde final ouvindo as outras vozes."],"minutos":12,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Barítono seguindo a melodia quando ela cruza a sua linha.","correcao":"Estude os pontos de cruzamento separadamente."},{"erro":"Primeiro tenor forçando a voz de peito no agudo.","correcao":"Use voz leve (mista ou de cabeça) e volume moderado."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e cantar uma parte do quarteto no modo conjunto."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'harmonia-tres-quatro-vozes' from public.lessons where slug = 'quarteto-masculino' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:quarteto-treinador')::uuid, 'quarteto-treinador', (select id from public.lessons where slug = 'quarteto-masculino'), 'Prática: sua voz no quarteto', 'Cante uma voz de “Que grande amor” no treinador.', 'harmony_part', '{"voices":4,"arrangementSlug":"que-grande-amor-ttbb"}'::jsonb, 'harmonia-tres-quatro-vozes', 'pratica', 3, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:quarteto-avaliacao')::uuid, 'quarteto-avaliacao', (select id from public.lessons where slug = 'quarteto-masculino'), 'Avaliação: vozes do quarteto masculino', 'Responda sobre a formação TTBB.', 'quiz', '{"questions":[{"q":"No estilo barbershop, o segundo tenor costuma ser chamado de “lead” porque…","options":["Canta a melodia","Rege o grupo","Canta mais forte","É o mais grave"],"answer":0},{"q":"Qual voz do quarteto mais frequentemente cruza a melodia?","options":["Barítono","Baixo","Primeiro tenor","Nenhuma"],"answer":0},{"q":"A nomenclatura das vozes num quarteto…","options":["Pode variar conforme o arranjo e a tradição","É sempre a mesma","Não existe","Depende só da altura dos cantores"],"answer":0},{"q":"Por que a afinação é tão sensível no quarteto masculino?","options":["As vozes ficam numa região próxima e o som é muito unido","Porque são só quatro pessoas","Porque não há melodia","Não é sensível"],"answer":0}]}'::jsonb, 'harmonia-tres-quatro-vozes', 'avaliacao', 3, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:afinacao-de-acordes')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'afinacao-de-acordes', 'Afinação de acordes', 'Afinação vertical: quando o acorde “encaixa”.', 5, 3, 20, '{"objetivo":"Perceber e ajustar a afinação vertical de acordes sustentados e reconhecer quando uma voz está acima ou abaixo.","explicacao":[{"type":"p","text":"Afinação horizontal é a de cada voz ao longo da melodia. Afinação vertical é a do acorde: quanto as notas cantadas ao mesmo tempo se encaixam. Quando o acorde está bem afinado, ele parece mais forte e “brilha” — às vezes ouvimos até notas que ninguém está cantando (harmônicos)."},{"type":"list","items":["Afine a partir do baixo: o baixo dá a referência; as outras vozes ajustam-se a ele.","Oitavas e quintas precisam estar exatas: são o “esqueleto” do acorde.","A terça maior encaixa um pouco mais baixa que no teclado; a terça menor, um pouco mais alta.","Notas longas tendem a cair: mantenha o apoio do ar até o fim."]}],"demonstracao":[{"type":"harmonyLink","arrangement":"acordes-sustentados-satb","label":"Acordes sustentados SATB"},{"type":"audio","label":"Quinta justa afinada (Dó3–Sol3)","notes":[["C3","G3"]],"mode":"chord","tempo":25}],"exercicioGuiado":{"passos":["Nos acordes sustentados, cante a sua voz no modo guiado ouvindo o baixo.","Sustente cada acorde por 4 tempos prestando atenção ao “encaixe”.","Faça a avaliação de perceber notas acima ou abaixo com diferenças pequenas."]},"pratiqueSozinho":{"passos":["Laboratório: perceber desafinação no nível recomendado.","Acordes sustentados no modo conjunto."],"minutos":8,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Afinar pela voz mais forte do grupo.","correcao":"Afine pelo baixo e pela fundamental do acorde."},{"erro":"Deixar a nota cair no final.","correcao":"Mantenha o fluxo de ar e o espaço interno até o corte."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes."],"criterioAvanco":"Acertar pelo menos 70% na avaliação com diferenças de 25 cents."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
