insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:afinacao-acordes-treinador')::uuid, 'afinacao-acordes-treinador', (select id from public.lessons where slug = 'afinacao-de-acordes'), 'Prática: acordes sustentados', 'Cante a sua voz nos acordes sustentados.', 'harmony_part', '{"voices":4,"arrangementSlug":"acordes-sustentados-satb"}'::jsonb, 'harmonia-tres-quatro-vozes', 'pratica', 3, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:independencia-vocal')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'independencia-vocal', 'Independência vocal', 'Ouvir o conjunto sem abandonar a própria voz.', 6, 3, 25, '{"objetivo":"Manter a própria linha com todas as vozes soando no mesmo volume, inclusive com entradas independentes e melodias em movimento contrário.","explicacao":[{"type":"p","text":"Independência vocal é a capacidade de cantar a sua linha com segurança enquanto ouve o conjunto. Ela não significa ignorar os outros: significa ouvir, se localizar e continuar na sua parte."},{"type":"list","items":["Conheça a sua parte de cor antes do conjunto.","Saiba onde estão as notas-âncora e as entradas.","Ouça ativamente a voz imediatamente acima e abaixo da sua: elas são suas referências.","Se se perder, não pare o grupo: volte na próxima âncora ou na próxima frase."]}],"demonstracao":[{"type":"harmonyLink","arrangement":"canone-solfejo","label":"Cânone a quatro vozes"},{"type":"harmonyLink","arrangement":"hino-alegria-satb","label":"SATB no modo conjunto"}],"exercicioGuiado":{"passos":["Cante a voz 3 do cânone no modo conjunto (todas as vozes no mesmo volume).","Cante a sua voz do SATB no modo conjunto com a sua voz em volume igual às outras.","Faça a avaliação de sustentação com distração."]},"pratiqueSozinho":{"passos":["Cânone: cada dia uma voz diferente.","Sustentação com distração: 3 notas por dia."],"minutos":10,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Parar quando erra.","correcao":"No grupo, continue e retome na próxima âncora."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Média de 70% na sustentação com distração e voz cantada no modo conjunto."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
