insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:independencia-canone')::uuid, 'independencia-canone', (select id from public.lessons where slug = 'independencia-vocal'), 'Prática: cânone a quatro vozes', 'Cante uma voz do cânone no modo conjunto.', 'harmony_part', '{"voices":4,"arrangementSlug":"canone-solfejo"}'::jsonb, 'independencia-vocal', 'pratica', 3, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:independencia-avaliacao')::uuid, 'independencia-avaliacao', (select id from public.lessons where slug = 'independencia-vocal'), 'Avaliação: sustentação com distração', 'Sustente a sua nota enquanto outra melodia soa (use fones com o microfone).', 'sing_note', '{"rounds":4,"holdSeconds":5,"toleranceCents":25,"distractor":true}'::jsonb, 'independencia-vocal', 'avaliacao', 3, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:arranjos-avancados')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'arranjos-avancados', 'Arranjos avançados', 'Contracanto, pedal, dinâmica por naipe, modulação e adaptação de tonalidade.', 7, 3, 30, '{"objetivo":"Conhecer recursos de arranjo vocal — contracanto, pedal harmônico, introduções e interlúdios vocais, modulação, dinâmica por naipe e construção de clímax — e saber adaptar a tonalidade ao grupo.","explicacao":[{"type":"list","items":["Contracanto: uma segunda melodia independente, geralmente acima da principal (descante), que dialoga com ela.","Pedal harmônico: nota sustentada (muitas vezes a tônica ou a dominante, no baixo) enquanto os acordes mudam acima dela.","Introduções e interlúdios vocais: trechos em “u”, “m” ou com sílabas que preparam a entrada do texto.","Modulação: mudança de tonalidade, muito usada para elevar a última estrofe (geralmente um tom acima).","Rearmonização introdutória: trocar alguns acordes da harmonia original (ex.: usar vi no lugar de I) mantendo a melodia.","Acordes de passagem: acordes rápidos que ligam dois acordes principais.","Dinâmica por naipe e clímax: naipes entram aos poucos, a dinâmica cresce e o ponto mais alto coincide com a frase mais importante do texto."]},{"type":"tip","title":"Adaptar a tonalidade","text":"A melhor tonalidade é a que coloca a melodia na região confortável do grupo e da congregação. Para louvor congregacional, mantenha a melodia aproximadamente entre Si♭3 e Ré5. O treinador de harmonia permite transpor os exercícios para testar."}],"demonstracao":[{"type":"harmonyLink","arrangement":"hino-alegria-contracanto","label":"Hino da Alegria com contracanto e pedal"},{"type":"harmonyLink","arrangement":"pedal-e-melodia","label":"Nota pedal e melodia"}],"exercicioGuiado":{"passos":["Ouça o arranjo com contracanto no modo conjunto e identifique as três camadas.","Cante o contracanto (vozes agudas) ou o pedal (vozes graves) no modo guiado.","Use a transposição do treinador: +2 semitons. A melodia ficou mais confortável para o grupo?","Planeje a dinâmica: qual compasso é o clímax do texto?"]},"pratiqueSozinho":{"passos":["Treinador: contracanto ou pedal no modo conjunto.","Escolha uma música do repertório e anote onde caberia um pedal ou uma modulação."],"minutos":15,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Contracanto mais forte que a melodia.","correcao":"O contracanto colore; a melodia continua sendo a principal."},{"erro":"Modular sem preparar a nova nota de entrada.","correcao":"Ensaiem a passagem da modulação separadamente."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
