insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:avancado-treinador')::uuid, 'avancado-treinador', (select id from public.lessons where slug = 'arranjos-avancados'), 'Prática: contracanto e pedal', 'Cante uma camada do arranjo com contracanto.', 'harmony_part', '{"voices":3,"arrangementSlug":"hino-alegria-contracanto"}'::jsonb, 'harmonia-tres-quatro-vozes', 'pratica', 3, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:avancado-avaliacao')::uuid, 'avancado-avaliacao', (select id from public.lessons where slug = 'arranjos-avancados'), 'Avaliação: recursos de arranjo', 'Responda sobre arranjos avançados.', 'quiz', '{"questions":[{"q":"Uma nota sustentada no baixo enquanto os acordes mudam acima é um…","options":["Pedal harmônico","Contracanto","Cânone","Acorde de passagem"],"answer":0},{"q":"Contracanto é…","options":["Uma segunda melodia independente que dialoga com a principal","A melodia cantada mais forte","Cantar sem texto","Um tipo de respiração"],"answer":0},{"q":"Uma modulação comum para a última estrofe é…","options":["Subir um tom","Descer uma oitava","Mudar para compasso ternário","Retirar o baixo"],"answer":0},{"q":"O critério principal para escolher a tonalidade de um louvor congregacional é…","options":["A região confortável do grupo e da congregação","A tonalidade da gravação original","A preferência do instrumentista","Ser sempre Dó maior"],"answer":0},{"q":"Ouça: há uma nota grave sustentada enquanto a melodia se move?","options":["Sim, um pedal","Não"],"answer":0,"audio":{"notes":[["C3","C4"],["C3","D4"],["C3","E4"],["C3","F4"],["C3","E4"]],"mode":"seq","tempo":80}}]}'::jsonb, 'teoria-harmonia', 'avaliacao', 3, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:leitura-musical')::uuid, 'leitura-musical', 'E', 'Leitura musical', 'Da pauta à partitura vocal', 'Ler música dá autonomia para estudar a própria voz. A trilha cobre notas na pauta, figuras rítmicas e compassos, claves, intervalos escritos, cifras e a leitura de partituras corais.', 'book-open', 4) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:notas-na-pauta')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'notas-na-pauta', 'Notas na pauta', 'Linhas, espaços e a clave de Sol.', 0, 1, 20, '{"objetivo":"Ler as notas naturais na clave de Sol, da região do dó central até o Sol5.","explicacao":[{"type":"p","text":"A pauta (ou pentagrama) tem cinco linhas e quatro espaços, contados de baixo para cima. Cada linha e cada espaço representam uma nota; quanto mais acima, mais aguda. Para notas além da pauta, usamos linhas suplementares."},{"type":"p","text":"A clave de Sol é desenhada começando na 2ª linha: por isso, a nota na 2ª linha é Sol (Sol4). A partir daí, as notas seguem em ordem: linha, espaço, linha, espaço…"},{"type":"list","items":["Linhas (de baixo para cima) na clave de Sol: Mi4, Sol4, Si4, Ré5, Fá5.","Espaços (de baixo para cima): Fá4, Lá4, Dó5, Mi5 — formam a palavra “FALADOMI” (Fá-Lá-Dó-Mi).","Dó4 (dó central) fica numa linha suplementar abaixo da pauta.","Ré4 fica logo abaixo da 1ª linha."]},{"type":"tip","title":"Notas-âncora","text":"Memorize três âncoras: Dó4 (linha suplementar), Sol4 (2ª linha, onde a clave começa) e Dó5 (3º espaço). As outras você encontra contando a partir delas."}],"demonstracao":[{"type":"staff","clef":"sol","notes":["C4","D4","E4","F4","G4","A4","B4","C5"],"label":"Escala de Dó4 a Dó5 na clave de Sol"},{"type":"staff","clef":"sol","notes":["E4","G4","B4","D5","F5"],"label":"Notas nas linhas"},{"type":"staff","clef":"sol","notes":["F4","A4","C5","E5"],"label":"Notas nos espaços (FALADOMI)"},{"type":"keyboard","from":"C4","to":"G5","highlight":["C4","G4","C5"],"label":"As três notas-âncora no teclado"}],"exercicioGuiado":{"passos":["Diga em voz alta as notas das linhas e dos espaços olhando as demonstrações.","Toque cada nota no teclado enquanto lê.","Faça a prática com as notas entre Dó4 e Dó5.","Faça a avaliação até o Sol5."]},"pratiqueSozinho":{"passos":["5 minutos de leitura de notas por dia.","Leia a linha do soprano de um hino conhecido dizendo os nomes das notas."],"minutos":5,"frequencia":"Diariamente por duas semanas"},"errosComuns":[{"erro":"Contar as linhas de cima para baixo.","correcao":"Linhas e espaços são contados de baixo para cima."},{"erro":"Confundir notas em linha e em espaço vizinhos.","correcao":"Olhe se a linha passa pelo meio da nota (linha) ou se a nota está entre duas linhas (espaço)."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% na avaliação de leitura na clave de Sol."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'leitura-pauta' from public.lessons where slug = 'notas-na-pauta' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:pauta-pratica')::uuid, 'pauta-pratica', (select id from public.lessons where slug = 'notas-na-pauta'), 'Prática: Dó4 a Dó5', 'Qual é o nome da nota?', 'staff_read', '{"rounds":8,"clef":"sol","range":["C4","C5"]}'::jsonb, 'leitura-pauta', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:pauta-avaliacao')::uuid, 'pauta-avaliacao', (select id from public.lessons where slug = 'notas-na-pauta'), 'Avaliação: clave de Sol', 'Qual é o nome da nota?', 'staff_read', '{"rounds":10,"clef":"sol","range":["C4","G5"]}'::jsonb, 'leitura-pauta', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:figuras-ritmicas-e-compassos')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'figuras-ritmicas-e-compassos', 'Ritmo: figuras e compassos', 'Semibreve, mínima, semínima, colcheia, pausas e fórmulas de compasso.', 1, 1, 25, '{"objetivo":"Ler as figuras rítmicas e as pausas mais comuns e compreender os compassos simples 2/4, 3/4 e 4/4.","explicacao":[{"type":"list","items":["Semibreve: 4 tempos (em compassos de semínima).","Mínima: 2 tempos.","Semínima: 1 tempo.","Colcheia: meio tempo (duas por tempo).","Semicolcheia: um quarto de tempo (quatro por tempo).","O ponto de aumento acrescenta metade do valor: mínima pontuada = 3 tempos; semínima pontuada = 1 tempo e meio.","Cada figura tem uma pausa correspondente, com a mesma duração em silêncio."]},{"type":"p","text":"A fórmula de compasso aparece no início da música. O número de cima indica quantos tempos há em cada compasso; o de baixo, qual figura vale um tempo (4 = semínima). Assim, 3/4 tem três semínimas por compasso — o compasso de muitos hinos, como “Que grande amor”."}],"demonstracao":[{"type":"rhythm","pattern":"w","bpm":80,"label":"Semibreve (4 tempos)"},{"type":"rhythm","pattern":"h h","bpm":80,"label":"Duas mínimas"},{"type":"rhythm","pattern":"q q q q","bpm":80,"label":"Quatro semínimas"},{"type":"rhythm","pattern":"e e e e e e e e","bpm":80,"label":"Oito colcheias"},{"type":"rhythm","pattern":"h. q","bpm":80,"label":"Mínima pontuada e semínima"},{"type":"rhythm","pattern":"q. e q q","bpm":80,"label":"Semínima pontuada, colcheia e duas semínimas"}],"exercicioGuiado":{"passos":["Com o metrônomo, fale “tá” em cada semínima e “tá-a” nas mínimas.","Fale “ti-ti” nas colcheias.","Ouça a “semínima pontuada + colcheia”: “tá—a-ti”. É o ritmo de “har-mo-ni-a” no Hino da Alegria.","Faça a prática de leitura rítmica tocando os padrões."]},"pratiqueSozinho":{"passos":["Leia o ritmo da sua voz numa partitura do repertório, falando as sílabas no tempo.","Exercício de ritmo com padrões pontuados."],"minutos":8,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Ignorar o ponto de aumento.","correcao":"O ponto acrescenta metade do valor da figura."},{"erro":"Pular pausas.","correcao":"Pausas também são contadas: o silêncio faz parte do ritmo."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações de leitura rítmica."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
