insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:ritmo-pontuado-pratica')::uuid, 'ritmo-pontuado-pratica', (select id from public.lessons where slug = 'figuras-ritmicas-e-compassos'), 'Prática: ritmos pontuados', 'Ouça e reproduza.', 'rhythm_tap', '{"rounds":4,"patterns":["h. q","q. e q q","q q. e q","q. e h"],"bpm":72}'::jsonb, 'leitura-ritmica', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:figuras-avaliacao')::uuid, 'figuras-avaliacao', (select id from public.lessons where slug = 'figuras-ritmicas-e-compassos'), 'Avaliação: figuras e compassos', 'Responda sobre figuras e compassos.', 'quiz', '{"questions":[{"q":"Em 4/4, quantos tempos vale a mínima?","options":["2","1","4","3"],"answer":0},{"q":"Quantas colcheias cabem em um tempo de semínima?","options":["2","1","4","8"],"answer":0},{"q":"Quanto vale uma mínima pontuada?","options":["3 tempos","2 tempos","2 tempos e meio","4 tempos"],"answer":0},{"q":"No compasso 3/4, cada compasso tem…","options":["Três semínimas","Três mínimas","Quatro semínimas","Três colcheias"],"answer":0},{"q":"Uma pausa de semínima vale…","options":["1 tempo de silêncio","Meio tempo","2 tempos","Nenhum tempo"],"answer":0}]}'::jsonb, 'leitura-ritmica', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:claves')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'claves', 'Claves de Sol e de Fá', 'Leitura na clave de Fá e a clave de Sol do tenor.', 2, 2, 20, '{"objetivo":"Ler notas na clave de Fá (vozes graves) e entender a clave de Sol oitavada usada para o tenor.","explicacao":[{"type":"p","text":"A clave de Fá começa na 4ª linha, marcada pelos dois pontos ao redor dela: essa linha é Fá3. Ela é usada para baixos e, em muitos hinários, também para tenores."},{"type":"list","items":["Linhas na clave de Fá (de baixo para cima): Sol2, Si2, Ré3, Fá3, Lá3.","Espaços: Lá2, Dó3, Mi3, Sol3.","Dó4 (dó central) fica numa linha suplementar acima da pauta de Fá — a mesma nota da linha suplementar abaixo da pauta de Sol.","Clave de Sol com um 8 embaixo: usada pelo tenor; soa uma oitava abaixo do que está escrito."]},{"type":"tip","title":"Pauta dupla","text":"Nos hinários SATB, soprano e contralto leem na clave de Sol (pauta de cima), tenor e baixo na clave de Fá (pauta de baixo). O dó central liga as duas pautas."}],"demonstracao":[{"type":"staff","clef":"fa","notes":["G2","B2","D3","F3","A3"],"label":"Linhas na clave de Fá"},{"type":"staff","clef":"fa","notes":["A2","C3","E3","G3"],"label":"Espaços na clave de Fá"},{"type":"staff","clef":"fa","notes":["C3","D3","E3","F3","G3","A3","B3","C4"],"label":"Escala de Dó3 a Dó4"}],"exercicioGuiado":{"passos":["Leia em voz alta as linhas e espaços da clave de Fá.","Toque no teclado as notas da escala de Dó3 a Dó4 enquanto lê.","Faça a prática e a avaliação."]},"pratiqueSozinho":{"passos":["5 minutos de leitura na clave de Fá.","Leia a linha do baixo de um hino conhecido."],"minutos":5,"frequencia":"Diariamente por duas semanas"},"errosComuns":[{"erro":"Ler a clave de Fá como se fosse a de Sol.","correcao":"Comece sempre pela âncora: a 4ª linha é Fá."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% na avaliação da clave de Fá."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
