insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:clave-fa-avaliacao')::uuid, 'clave-fa-avaliacao', (select id from public.lessons where slug = 'claves'), 'Avaliação: claves de Sol e de Fá', 'As notas aparecem nas duas claves.', 'staff_read', '{"rounds":10,"clef":"ambas"}'::jsonb, 'leitura-pauta', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:intervalos-na-pauta')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'intervalos-na-pauta', 'Intervalos na pauta', 'Ver e ouvir a distância entre as notas escritas.', 3, 2, 20, '{"objetivo":"Reconhecer intervalos na pauta pela posição das notas e relacioná-los ao som.","explicacao":[{"type":"list","items":["Segunda: de linha para o espaço vizinho (notas “encostadas”).","Terça: de linha para a linha seguinte, ou de espaço para o espaço seguinte.","Quarta: de linha para espaço, pulando uma linha.","Quinta: de linha para linha pulando uma, ou de espaço para espaço pulando um.","Oitava: linha ↔ espaço com mesma letra (Dó4 → Dó5)."]},{"type":"p","text":"Saber ver um intervalo ajuda a cantar à primeira vista: se a sua próxima nota está uma terça acima, você já sabe que é a distância do início de um acorde maior ou menor."}],"demonstracao":[{"type":"staff","clef":"sol","notes":["E4","G4"],"label":"Terça (linha → linha)"},{"type":"staff","clef":"sol","notes":["G4","D5"],"label":"Quinta (linha → linha pulando uma)"},{"type":"staff","clef":"sol","notes":["C4","C5"],"label":"Oitava"},{"type":"intervals","root":"E4","semitones":[3,7,12]}],"exercicioGuiado":{"passos":["Observe as demonstrações e toque cada intervalo.","Cante cada intervalo depois de ouvi-lo.","Faça a avaliação de intervalos na pauta."]},"pratiqueSozinho":{"passos":["Na sua partitura, circule os saltos de terça, quinta e oitava da sua voz e cante-os separadamente."],"minutos":6,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Contar o intervalo sem incluir a primeira nota.","correcao":"Conte as duas notas: de Dó a Mi são três notas (Dó, Ré, Mi) — terça."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% na avaliação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'leitura-pauta' from public.lessons where slug = 'intervalos-na-pauta' on conflict do nothing;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'intervalos' from public.lessons where slug = 'intervalos-na-pauta' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:intervalos-pauta-avaliacao')::uuid, 'intervalos-pauta-avaliacao', (select id from public.lessons where slug = 'intervalos-na-pauta'), 'Avaliação: intervalos escritos', 'Observe as notas na pauta e ouça.', 'quiz', '{"questions":[{"q":"Que intervalo é este?","options":["Terça","Segunda","Quinta","Oitava"],"answer":0,"staff":{"clef":"sol","notes":["E4","G4"]},"audio":{"notes":["E4","G4"],"mode":"seq","tempo":70}},{"q":"Que intervalo é este?","options":["Quinta","Terça","Quarta","Sexta"],"answer":0,"staff":{"clef":"sol","notes":["G4","D5"]},"audio":{"notes":["G4","D5"],"mode":"seq","tempo":70}},{"q":"Que intervalo é este?","options":["Segunda","Terça","Uníssono","Quarta"],"answer":0,"staff":{"clef":"sol","notes":["A4","B4"]},"audio":{"notes":["A4","B4"],"mode":"seq","tempo":70}},{"q":"Que intervalo é este?","options":["Oitava","Sétima","Quinta","Sexta"],"answer":0,"staff":{"clef":"sol","notes":["C4","C5"]},"audio":{"notes":["C4","C5"],"mode":"seq","tempo":70}},{"q":"Que intervalo é este?","options":["Quarta","Terça","Quinta","Segunda"],"answer":0,"staff":{"clef":"sol","notes":["D4","G4"]},"audio":{"notes":["D4","G4"],"mode":"seq","tempo":70}},{"q":"Que intervalo é este (clave de Fá)?","options":["Terça","Quinta","Segunda","Oitava"],"answer":0,"staff":{"clef":"fa","notes":["C3","E3"]},"audio":{"notes":["C3","E3"],"mode":"seq","tempo":70}}]}'::jsonb, 'leitura-pauta', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:cifras')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'cifras', 'Cifras', 'Letras, acidentes e sufixos dos acordes.', 4, 2, 20, '{"objetivo":"Ler cifras (C, Am, G7, D/F♯…) e identificar as notas que formam cada acorde.","explicacao":[{"type":"list","items":["Letras: A = Lá, B = Si, C = Dó, D = Ré, E = Mi, F = Fá, G = Sol.","Acidentes: ♯ (sustenido) sobe meio-tom; ♭ (bemol) desce meio-tom. Ex.: F♯ = Fá sustenido; B♭ = Si bemol.","Letra sozinha = acorde maior (C = Dó maior: Dó, Mi, Sol).","“m” = menor (Am = Lá menor: Lá, Dó, Mi).","“7” = sétima menor acrescentada (G7 = Sol, Si, Ré, Fá).","“7M” ou “maj7” = sétima maior (C7M = Dó, Mi, Sol, Si).","“°” ou “dim” = diminuto; “+” ou “aug” = aumentado.","Barra = baixo invertido: D/F♯ é Ré maior com Fá♯ no baixo."]},{"type":"p","text":"Para quem canta, a cifra ajuda a saber em que acorde a sua nota está. Se a cifra é C e você canta Mi, você está na terça do acorde; se canta Sol, está na quinta."}],"demonstracao":[{"type":"chords","root":"C4","qualities":["maior","menor","dominante7"]},{"type":"audio","label":"G7 (Sol–Si–Ré–Fá)","notes":[["G3","B3","D4","F4"]],"mode":"chord","tempo":30},{"type":"audio","label":"D/F♯ (Ré maior com Fá♯ no baixo)","notes":[["F#3","D4","F#4","A4"]],"mode":"chord","tempo":30}],"exercicioGuiado":{"passos":["Escreva as notas de C, F, G e Am.","Toque-as no teclado e confira com as demonstrações.","Faça a avaliação de cifras."]},"pratiqueSozinho":{"passos":["Pegue a cifra de um hino do repertório e escreva as notas de cada acorde.","Identifique em que nota do acorde a sua voz está em cada sílaba forte."],"minutos":10,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Confundir “7” com “7M”.","correcao":"“7” é sétima menor (a mais comum); “7M” é sétima maior."},{"erro":"Ler “Bm” como Si maior.","correcao":"O “m” minúsculo indica menor."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% na avaliação de cifras."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'cifras' from public.lessons where slug = 'cifras' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:cifras-avaliacao')::uuid, 'cifras-avaliacao', (select id from public.lessons where slug = 'cifras'), 'Avaliação: lendo cifras', 'Responda sobre cifras.', 'quiz', '{"questions":[{"q":"Quais notas formam o acorde G?","options":["Sol, Si, Ré","Sol, Si♭, Ré","Sol, Dó, Mi","Lá, Dó, Mi"],"answer":0},{"q":"Quais notas formam o acorde Am?","options":["Lá, Dó, Mi","Lá, Dó♯, Mi","Lá, Ré, Fá","Mi, Sol, Si"],"answer":0},{"q":"O que significa a cifra D/F♯?","options":["Ré maior com Fá♯ no baixo","Ré e Fá♯ alternados","Ré menor","Fá♯ maior"],"answer":0},{"q":"A letra E corresponde a…","options":["Mi","Ré","Fá","Lá"],"answer":0},{"q":"Quantas notas tem o acorde C7?","options":["Quatro (Dó, Mi, Sol, Si♭)","Três","Sete","Duas"],"answer":0},{"q":"Ouça: este acorde é C ou Cm?","options":["Cm","C"],"answer":0,"audio":{"notes":[["C4","D#4","G4"]],"mode":"chord","tempo":30}}]}'::jsonb, 'cifras', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:leitura-de-partituras-vocais')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'leitura-de-partituras-vocais', 'Leitura aplicada a partituras vocais', 'Encontrar a sua voz, o texto, as respirações e as indicações.', 5, 2, 25, '{"objetivo":"Orientar-se numa partitura coral: sistemas, pautas, a própria voz, texto, repetições, dinâmicas e marcações de estudo.","explicacao":[{"type":"list","items":["Sistema: conjunto de pautas lidas ao mesmo tempo. Num hinário SATB, duas pautas (S/C em cima, T/B embaixo).","Hastes para cima e para baixo: na mesma pauta, hastes para cima = voz de cima (soprano ou tenor); para baixo = voz de baixo (contralto ou baixo).","Texto: fica entre as pautas; as estrofes aparecem numeradas.","Sinais de repetição (:‖), casas de 1ª e 2ª vez, D.C. (do início) e D.S. (do sinal) indicam o caminho da leitura.","Dinâmicas (p, mf, f), crescendo e respirações (vírgula ou “V”).","Fermata (𝄐): sustente a nota além do valor, conforme o regente.","Números de compasso ajudam a combinar onde recomeçar no ensaio."]},{"type":"tip","title":"Marcações a lápis","text":"Marque a sua voz com marca-texto, as respirações com “V” e os trechos difíceis com um círculo. Revise as marcações após cada ensaio."}],"demonstracao":[{"type":"staff","clef":"sol","notes":["E4","E4","F4","G4"],"label":"Primeiro compasso do soprano no Hino da Alegria"},{"type":"staff","clef":"fa","notes":["C3","C3","F3","C3"],"label":"Primeiro compasso do baixo no Hino da Alegria"},{"type":"harmonyLink","arrangement":"hino-alegria-satb","label":"Siga a sua voz no treinador com a representação das notas"}],"exercicioGuiado":{"passos":["Abra o Hino da Alegria SATB no treinador e acompanhe a sua voz na representação de notas.","Identifique em que compasso há um ritmo pontuado.","Leia o ritmo falando o texto antes de cantar.","Marque respirações e trechos difíceis (no treinador, use “marcar trecho”)."]},"pratiqueSozinho":{"passos":["Prepare a sua voz de uma música do repertório com marcações a lápis.","Leve dúvidas para o professor."],"minutos":15,"frequencia":"1 vez por semana"},"errosComuns":[{"erro":"Seguir a haste errada na pauta compartilhada.","correcao":"Confira a direção das hastes da sua voz."},{"erro":"Esquecer as repetições.","correcao":"Antes de cantar, percorra o “caminho” da partitura com o dedo."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% da avaliação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
