insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:partitura-avaliacao')::uuid, 'partitura-avaliacao', (select id from public.lessons where slug = 'leitura-de-partituras-vocais'), 'Avaliação: orientação na partitura', 'Responda sobre leitura de partituras vocais.', 'quiz', '{"questions":[{"q":"Na pauta de cima de um hinário SATB, as notas com haste para baixo são do…","options":["Contralto","Soprano","Tenor","Baixo"],"answer":0},{"q":"O sinal de fermata indica…","options":["Sustentar a nota além do valor, conforme o regente","Repetir o trecho","Cantar forte","Respirar"],"answer":0},{"q":"D.C. significa…","options":["Voltar ao início","Ir para o sinal","Diminuir o volume","Cantar mais devagar"],"answer":0},{"q":"Para que servem os números de compasso no ensaio?","options":["Combinar de onde recomeçar","Indicar a dinâmica","Contar os cantores","Indicar a tonalidade"],"answer":0}]}'::jsonb, 'leitura-pauta', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:teoria-aplicada')::uuid, 'teoria-aplicada', 'F', 'Teoria aplicada', 'Escalas, acordes, campo harmônico e transposição', 'Teoria a serviço do ministério: entender por que as vozes se encaixam, como os acordes funcionam numa música e como escolher a tonalidade certa para o grupo.', 'library', 5) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:escalas-tons-e-semitons')::uuid, (select id from public.learning_paths where slug = 'teoria-aplicada'), 'escalas-tons-e-semitons', 'Escalas, tons, semitons e armaduras', 'A fórmula da escala maior e menor e as armaduras de clave.', 0, 2, 25, '{"objetivo":"Construir escalas maiores e menores a partir de tons e semitons e reconhecer as armaduras de clave mais usadas.","explicacao":[{"type":"p","text":"Semitom é a menor distância entre duas notas no teclado (tecla vizinha, branca ou preta). Tom são dois semitons. Entre Mi–Fá e Si–Dó há apenas um semitom, por isso não existe tecla preta entre elas."},{"type":"list","items":["Escala maior: T T S T T T S (Dó maior: Dó Ré Mi Fá Sol Lá Si Dó).","Escala menor natural: T S T T S T T (Lá menor: Lá Si Dó Ré Mi Fá Sol Lá).","Menor harmônica: menor natural com o 7º grau elevado — cria a sensível que conduz à tônica.","Toda tonalidade maior tem uma relativa menor com a mesma armadura (Dó maior ↔ Lá menor)."]},{"type":"p","text":"A armadura de clave, logo após a clave, indica os sustenidos ou bemóis da tonalidade. Ordem dos sustenidos: Fá, Dó, Sol, Ré, Lá, Mi, Si. Ordem dos bemóis: Si, Mi, Lá, Ré, Sol, Dó, Fá. Exemplos: Sol maior = 1♯ (Fá♯); Ré maior = 2♯; Fá maior = 1♭ (Si♭); Si♭ maior = 2♭."},{"type":"tip","title":"Truque das armaduras","text":"Com sustenidos, a tônica maior fica meio-tom acima do último sustenido. Com bemóis, a tônica é o penúltimo bemol (exceto Fá maior, com um bemol)."}],"demonstracao":[{"type":"scales","tonic":"C4","kinds":["maior","menor_natural","menor_harmonica"]},{"type":"keyboard","from":"C4","to":"C5","highlight":["E4","F4","B4","C5"],"label":"Semitons naturais: Mi–Fá e Si–Dó"}],"exercicioGuiado":{"passos":["Construa a escala de Sol maior seguindo T T S T T T S no teclado (você vai precisar do Fá♯).","Construa Fá maior (você vai precisar do Si♭).","Ouça as escalas maior e menor e cante-as.","Faça a avaliação."]},"pratiqueSozinho":{"passos":["Laboratório: escalas maior e menor.","Descubra a armadura de duas músicas do repertório."],"minutos":10,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Esquecer os semitons naturais Mi–Fá e Si–Dó.","correcao":"Olhe o teclado: não há tecla preta entre eles."}],"seguranca":["Alterne teoria e prática: depois de cada conceito, toque e cante o exemplo."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
