insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:escalas-escuta-avaliacao')::uuid, 'escalas-escuta-avaliacao', (select id from public.lessons where slug = 'escalas-tons-e-semitons'), 'Avaliação: maior ou menor?', 'Ouça a escala.', 'scale_id', '{"rounds":6,"scales":["maior","menor_natural"]}'::jsonb, 'teoria-escalas', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:escalas-teoria-avaliacao')::uuid, 'escalas-teoria-avaliacao', (select id from public.lessons where slug = 'escalas-tons-e-semitons'), 'Avaliação: escalas e armaduras', 'Responda sobre escalas e armaduras.', 'quiz', '{"questions":[{"q":"Qual é a fórmula da escala maior?","options":["T T S T T T S","T S T T S T T","S T T S T T T","T T T S T T S"],"answer":0},{"q":"Quantos semitons há em um tom?","options":["2","1","3","12"],"answer":0},{"q":"Qual é a armadura de Sol maior?","options":["1 sustenido (Fá♯)","1 bemol (Si♭)","2 sustenidos","Nenhum acidente"],"answer":0},{"q":"Qual é a relativa menor de Dó maior?","options":["Lá menor","Dó menor","Mi menor","Ré menor"],"answer":0},{"q":"Entre quais notas naturais há apenas um semitom?","options":["Mi–Fá e Si–Dó","Dó–Ré e Fá–Sol","Lá–Si e Ré–Mi","Sol–Lá e Dó–Ré"],"answer":0},{"q":"Uma armadura com 2 bemóis (Si♭ e Mi♭) indica, no modo maior…","options":["Si♭ maior","Mi♭ maior","Fá maior","Ré maior"],"answer":0}]}'::jsonb, 'teoria-escalas', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:triades-e-inversoes')::uuid, (select id from public.learning_paths where slug = 'teoria-aplicada'), 'triades-e-inversoes', 'Tríades e inversões', 'Acordes maiores, menores, diminutos e aumentados; estado fundamental e inversões.', 1, 2, 25, '{"objetivo":"Formar tríades maiores, menores, diminutas e aumentadas e reconhecer o estado fundamental e as inversões.","explicacao":[{"type":"list","items":["Maior: terça maior + terça menor (Dó–Mi–Sol).","Menor: terça menor + terça maior (Dó–Mi♭–Sol).","Diminuta: terça menor + terça menor (Si–Ré–Fá).","Aumentada: terça maior + terça maior (Dó–Mi–Sol♯)."]},{"type":"list","items":["Estado fundamental: a fundamental está no baixo (Dó–Mi–Sol).","1ª inversão: a terça no baixo (Mi–Sol–Dó). Cifra: C/E.","2ª inversão: a quinta no baixo (Sol–Dó–Mi). Cifra: C/G."]},{"type":"p","text":"Inversões permitem que as vozes se movam pouco entre acordes — por isso os arranjos vocais as usam o tempo todo. Para quem canta, saber se o acorde está invertido ajuda a entender por que a sua nota é a mais grave ou a mais aguda naquele momento."}],"demonstracao":[{"type":"chords","root":"C4","qualities":["maior","menor","diminuto","aumentado"]},{"type":"audio","label":"Dó maior: estado fundamental, 1ª e 2ª inversão","notes":[["C4","E4","G4"],["E4","G4","C5"],["G4","C5","E5"]],"tempo":50}],"exercicioGuiado":{"passos":["Forme no teclado as quatro tríades sobre Ré.","Toque Fá maior nas três posições.","Faça a avaliação de tipos de acorde, incluindo diminuto e aumentado."]},"pratiqueSozinho":{"passos":["Laboratório de acordes (níveis 3 a 5).","Identifique uma inversão numa música do repertório (cifra com barra)."],"minutos":10,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Achar que a inversão muda o tipo do acorde.","correcao":"C/E continua sendo Dó maior; muda só a nota do baixo."}],"seguranca":["Alterne teoria e prática: depois de cada conceito, toque e cante o exemplo."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
