insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:triades-escuta-avaliacao')::uuid, 'triades-escuta-avaliacao', (select id from public.lessons where slug = 'triades-e-inversoes'), 'Avaliação: quatro tipos de tríade', 'Identifique o tipo de acorde.', 'chord_quality', '{"rounds":8,"qualities":["maior","menor","diminuto","aumentado"],"play":"ambos"}'::jsonb, 'acordes', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:triades-teoria-avaliacao')::uuid, 'triades-teoria-avaliacao', (select id from public.lessons where slug = 'triades-e-inversoes'), 'Avaliação: formação e inversões', 'Responda sobre tríades e inversões.', 'quiz', '{"questions":[{"q":"Quais notas formam Ré menor?","options":["Ré, Fá, Lá","Ré, Fá♯, Lá","Ré, Fá, Lá♭","Ré, Sol, Si"],"answer":0},{"q":"Si–Ré–Fá é uma tríade…","options":["Diminuta","Menor","Maior","Aumentada"],"answer":0},{"q":"Mi–Sol–Dó é Dó maior em…","options":["1ª inversão","Estado fundamental","2ª inversão","Não é Dó maior"],"answer":0},{"q":"A cifra C/G indica…","options":["Dó maior com Sol no baixo (2ª inversão)","Dó e Sol tocados juntos apenas","Sol maior","Dó com sétima"],"answer":0},{"q":"Por que os arranjos vocais usam inversões?","options":["Para as vozes se moverem pouco entre os acordes","Para mudar o tipo do acorde","Para evitar o baixo","Porque soam mais forte"],"answer":0}]}'::jsonb, 'teoria-harmonia', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:campo-harmonico-e-funcoes')::uuid, (select id from public.learning_paths where slug = 'teoria-aplicada'), 'campo-harmonico-e-funcoes', 'Campo harmônico e funções', 'Os sete acordes da tonalidade e o papel de cada um.', 2, 3, 25, '{"objetivo":"Montar o campo harmônico maior e entender as funções de tônica, subdominante e dominante.","explicacao":[{"type":"p","text":"Campo harmônico é o conjunto de acordes formados sobre cada nota da escala, usando apenas as notas da tonalidade. Em Dó maior: C (I), Dm (ii), Em (iii), F (IV), G (V), Am (vi), B° (vii°). Em qualquer tonalidade maior o padrão é o mesmo: maior, menor, menor, maior, maior, menor, diminuto."},{"type":"list","items":["Tônica (I, e também iii e vi): repouso, “casa”.","Subdominante (IV, e também ii): afastamento, preparação.","Dominante (V e vii°): tensão que pede resolução na tônica."]},{"type":"tip","title":"Graus em algarismos romanos","text":"Usar I–IV–V em vez de C–F–G permite falar da harmonia em qualquer tom. Por isso as progressões do laboratório aparecem em algarismos romanos."}],"demonstracao":[{"type":"audio","label":"Campo harmônico de Dó maior","notes":[["C4","E4","G4"],["D4","F4","A4"],["E4","G4","B4"],["F4","A4","C5"],["G4","B4","D5"],["A4","C5","E5"],["B4","D5","F5"]],"tempo":70},{"type":"audio","label":"I – IV – V – I (repouso, afastamento, tensão, repouso)","notes":[["C3","G3","C4","E4"],["F3","A3","C4","F4"],["G3","B3","D4","G4"],["C3","G3","C4","E4"]],"tempo":60}],"exercicioGuiado":{"passos":["Escreva o campo harmônico de Sol maior (G, Am, Bm, C, D, Em, F♯°).","Toque I–IV–V–I em Sol.","Faça a avaliação de progressões."]},"pratiqueSozinho":{"passos":["Laboratório de progressões.","Na cifra de uma música do repertório, escreva o grau de cada acorde."],"minutos":10,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Confundir o vi com um acorde “fora do tom”.","correcao":"Am faz parte de Dó maior: é o 6º grau, com função de tônica."}],"seguranca":["Alterne teoria e prática: depois de cada conceito, toque e cante o exemplo."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
